window.POEMS_DATA = JSON.parse("[{\"id\":2046,\"title\":\"Kiếp Nhân Sinh Đời Là Bể Khổ\",\"date\":\"2026-08-11T13:50:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Kiếp nhân sinh đời là bể khổ\\nTrải qua hết số kiếp an bài\\nRời cõi tạm để lại về cực lạc\\nBuông hết ngập ngừng, trả nợ trần ai.\\n\\nBao gian truân, vui buồn một cõi,\\nPhủ bụi thời gian nhẹ gót hài.\\nTóc điểm màu sương, tâm khép lại,\\nNhẹ nhàng như vệt nắng chiều phai.\\n\\nChẳng vương chốn bến mê mộng mị,\\nChẳng tiếc tơ lòng, đắng lẫn cay.\\nTrả lại nhân gian muôn đợt sóng,\\nTâm mây thong thả... cõi trời bay.\",\"local_images\":[\"images/poem_2046_img_0.webp\"]},{\"id\":2045,\"title\":\"Em Ơi Mỗi Sớm Mai Thức Dậy\",\"date\":\"2026-08-11T13:49:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Em ơi mỗi sớm mai thức dậy\\nBên cạnh mình không còn giấc mơ trưa.\\nAnh còn nhớ cái khoảnh khắc ấy\\nKhi con cất tiếng gọi \\\"ba ba\\\" đầu đời.\\n\\nCó lẽ bây giờ con chẳng nhớ\\nNhưng với anh như còn trong nhịp thở.\\nGiọt nước mắt rơi nghiêng gò má,\\nLòng ngập tràn hạnh phúc ngọt ngào.\\n\\nĐôi bàn tay bé xíu cào cào,\\nĐã giữ chặt tim anh từ dạo ấy.\\nĐời ngoài kia có muôn vàn sóng dội,\\nCó chông gai, xuôi ngược chốn bôn ba,\\n\\nChỉ cần nghe tiếng con gọi \\\"ba ba\\\",\\nBao mệt mỏi hóa nhẹ nhàng như gió.\\nMai con lớn bước đi trên đường rộng,\\nBối rối nào rồi cũng sẽ trôi qua.\\n\\nKý ức ngày đầu như nhành hoa nhỏ,\\nAnh nguyện giữ tròn... làm ấm cả đời ta.\",\"local_images\":[\"images/poem_2045_img_0.webp\"]},{\"id\":2044,\"title\":\"Khi Nào Gió Ngược Về Xuôi\",\"date\":\"2026-08-11T13:48:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Khi nào gió ngược về xuôi\\nLòng anh cảm thấy bùi ngùi nhớ em.\\nTrăng treo nghiêng vạt bên hiên,\\nNhặt gom kỷ niệm gửi miền xa xôi.\\n\\nĐường đời muôn lối chia đôi,\\nTình xưa như vết mực rơi vắt hàng.\\nChiều buông trút giọt nắng tàn,\\nTay ôm nỗi nhớ ngút ngàn dông bão.\\n\\nTrả em về cõi xôn xao,\\nTrả anh góc nhỏ nghẹn ngào đơn côi.\\nDẫu cho lòng có ngậm ngùi,\\nMong em trọn kiếp an vui một đời...\",\"local_images\":[\"images/poem_2044_img_0.webp\"]},{\"id\":2043,\"title\":\"Lòng Là Tĩnh Lặng\",\"date\":\"2026-08-11T13:47:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Lòng là tĩnh lặng\\nNhớ là dài lâu\\nLòng bớt âu sầu\\nTim thì không đau.\\n\\nĐường đời thong thả\\nQua những chênh chao\\nNhặt vệt nắng chiều\\nGửi vào chiêm bao.\\n\\nChút tình gửi lại\\nMấy mươi mùa sang\\nBuông hết ngỡ ngàng\\nTâm bình nhẹ bước.\\n\\nChẳng mong, chẳng ước\\nChẳng vướng gợn sóng\\nNhìn đời mênh mông\\nCõi lòng an nhiên...\",\"local_images\":[\"images/poem_2043_img_0.webp\"]},{\"id\":2042,\"title\":\"Con Sóng Bạc Đầu, Sóng Vỗ Về Đâu\",\"date\":\"2026-08-11T13:46:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Con sóng bạc đầu, sóng vỗ về đâu\\nLòng ta giữ âu sầu không tan biến.\\nChiều buông xuống nghiêng triền chân mây tím,\\nNhặt mảnh tình chôn giấu phía biển sâu.\\n\\nBiển ngoài kia vẫn cuộn thắt gầm gào,\\nNhư tiếng lòng tựa ngàn vạn nỗi đau.\\nDẫu bờ cát nghìn năm trôi lặng lẽ,\\nSóng bạc đầu vẫn khắc khoải đợi nhau.\\n\\nTrả nỗi sầu cho gió thoảng mây bay,\\nTrả cho biển những nghẹn ngào, đắng cay.\\nTa nhặt chút bình yên còn sót lại,\\nGhì chặt tim mình... qua những hao gầy.\",\"local_images\":[\"images/poem_2042_img_0.webp\"]},{\"id\":2041,\"title\":\"Em Cho Anh Biết Mộng Mơ\",\"date\":\"2026-08-11T13:45:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Em cho anh biết mộng mơ\\nEm cho anh biết mong chờ\\nĐể rồi em đi, để lại trong anh tan vỡ\\nNhững giấc mơ chẳng bao giờ, chẳng bao giờ nữa...\\n\\nCăn phòng vắng tiếng cười xưa lặng ngắt\\nGiọt mưa rơi buốt giá khóe môi mềm.\\nTay trót nắm sao chớp mắt buông vội,\\nTrả lại anh cả đêm dài thức giấc.\\n\\nLời thề cũ giờ hóa thành tàn tro,\\nLối anh về ngập tràn bóng bâng quơ.\\nCố tự dặn lòng qua mùa giông bão,\\nMà sao tim vẫn nghẹn thắt từng giờ...\\n\\nEm bước đi mang theo miền nắng ấm,\\nĐể lại đây riêng anh với hoài hoài...\",\"local_images\":[\"images/poem_2041_img_0.webp\"]},{\"id\":2040,\"title\":\"Lỡ Bước Sang Ngang Bóng Chiều Tà\",\"date\":\"2026-08-11T13:44:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Lỡ bước sang ngang bóng chiều tà\\nDáng người con gái đã rời xa.\\nSông xưa lặng lẽ dòng trôi chảy,\\nPhủ kín bến đời vệt rêu hoa.\\n\\nNhặt chút hương xưa vương mái tóc,\\nNhìn vệt nắng tàn rớt bên sông.\\nNgười đi xuôi dạt miền nhung gấm,\\nTa bước ngược chiều... hứng tay không.\\n\\nGió lạnh thổi qua hàng trúc rủ,\\nNghe câu hoài niệm xót xa lòng.\\nĐành thôi khép lại thời dại khờ,\\nGửi mảnh tình riêng chốn hư không.\",\"local_images\":[\"images/poem_2040_img_0.webp\"]},{\"id\":2039,\"title\":\"Anh Đến Bên Em Một Chiều Mưa\",\"date\":\"2026-08-11T13:43:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Anh đến bên em một chiều mưa\\nTóc xanh phủ trắng gió sương mờ\\nBóng dáng người thương mờ trong gió\\nNhư từng nhịp sóng vỗ vào bờ.\\n\\nPhút đầu gặp gỡ còn bỡ ngỡ\\nNhưng tựa bên nhau tự bao giờ.\\nCơn mưa che giấu niềm e ấp,\\nLòng ghép thành vần những ý thơ.\\n\\nTay nắm bàn tay ấm ngón mềm,\\nNghe thì thầm tiếng gió ru đêm.\\nBao nhiêu dông bão dừng sau cửa,\\nNhường lại không gian ngọt lịm êm.\\n\\nMưa vẫn rơi rơi trên mái hiên,\\nTa về nhặt lấy cõi bình yên.\\nDẫu đời dạt trôi muôn dặm thắm,\\nGiữ trọn tình này... vẹn nét duyên.\",\"local_images\":[\"images/poem_2039_img_0.webp\"]},{\"id\":2038,\"title\":\"Anh Với Em Như Hai Người Xa Lạ\",\"date\":\"2026-08-11T13:42:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Anh với em như hai người xa lạ\\nBước chung đường sao chẳng thể thấy nhau.\\nKhoảng cách gần mà ngỡ tựa vực sâu,\\nLời lặng im đè nặng góc tim đau.\\n\\nTa đã qua những mặn nồng ngày cũ,\\nĐể giờ đây ngoảnh mặt hóa dối gian.\\nCùng một mái hiên che mưa ngập lối,\\nMà lòng như hai thế giới muôn ngàn.\\n\\nThà ngàn trùng chia phôi nghìn dặm thắm,\\nCòn hơn gần mà ngạt thở, lạnh lùng.\\nTrả cho em lối đi về riêng biệt,\\nTrả cho ta chút bình lặng sau cùng...\",\"local_images\":[\"images/poem_2038_img_0.webp\"]},{\"id\":2037,\"title\":\"Tìm Trong Những Phút Bình Yên\",\"date\":\"2026-08-11T13:41:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Tìm trong những phút bình yên\\nCho ta thoát khỏi nhớ nhung muộn phiền.\\nTrả tình về chốn miên man,\\nTrả người về phía khung trời xa xôi.\\n\\nGió lùa nhẹ hạt sương rơi,\\nLòng như chiếc lá lặng bơi giữa dòng.\\nBắt tay làm hòa với hư không,\\nGom chút nắng hạ giấu vào nụ cười.\\n\\nĐời còn ngắn lắm, người ơi!\\nThôi không ôm mãi giọt rơi nghẹn ngào.\\nLắng nghe tiếng gió xì xào,\\nThấy tâm thanh thản... đi vào cõi thơ.\",\"local_images\":[\"images/poem_2037_img_0.webp\"]},{\"id\":2036,\"title\":\"Con Lớn Lên Bên Hình Hài Của Mẹ\",\"date\":\"2026-08-11T13:40:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Con lớn lên bên hình hài của mẹ\\nMắt xoe tròn hé mở cả tương lai\\nĐời còn dài, chông gai còn phía trước\\nSánh bên con mãi bước mẹ hiền.\\n\\nTrời chiều in những bóng tà\\nXa xa là bóng mẹ chờ mong con.\\nDẫu đi hết biển cùng non,\\nÂn tình của mẹ vẫn còn nguyên sâu.\\n\\nTóc sương điểm gieo sắc màu,\\nVẫn nâng bước nhỏ qua cơn gập ghềnh.\\nBình yên giấu giữa gập ghềnh,\\nThương con mẹ gánh cả ghềnh dông bão.\\n\\nCon đi giữa cõi lao đao,\\nVẫn quanh quẩn tiếng ca dao ngọt ngào...\",\"local_images\":[\"images/poem_2036_img_0.webp\"]},{\"id\":2035,\"title\":\"Đường Tình Ai Xẻ Làm Đôi\",\"date\":\"2026-08-11T13:39:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Đường tình ai xẻ làm đôi\\nNửa vui bên ấy, còn tôi nơi này.\\nNhìn chiều rớt giọt đắng cay,\\nRót ly rượu lạnh cạn ngày bão dông.\\n\\nNgười đi vui chén tơ hồng,\\nTa về gom nhặt hư không riêng mình.\\nLối xưa rêu phủ lặng thinh,\\nTrả thương, trả nhớ, trả tình đã qua.\\n\\nThôi thì một cõi xa xôi,\\nNguyện người êm ấm trọn đời an yên.\\nTôi xin giữ chút ưu phiền,\\nThả theo làn gió... về miền lãng quên.\",\"local_images\":[\"images/poem_2035_img_0.webp\"]},{\"id\":2034,\"title\":\"Đã Có Lúc Con Tim Như Trống Rỗng\",\"date\":\"2026-08-11T13:38:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Đã có lúc con tim như trống rỗng\\nGiữa hư không cho gió lạnh ùa về.\\nChiều buông xuống nghiêng dài vệt nắng nhạt,\\nTrút bâng khuâng lên khoảng trống muôn bề.\\n\\nĐã có lúc ngỡ lòng như hóa đá,\\nChẳng còn thương, chẳng vấn vương tình ai.\\nNgồi đếm bước chân rơi trên lối vắng,\\nNghe thời gian khẽ thở trút thở dài.\\n\\nRồi giọt đắng trôi qua niềm kiệt sức,\\nTrả nỗi sầu cho gió thoảng mây bay.\\nGom chút ấm giữ tròn nơi ngực trái,\\nTa tự vỗ về... qua những đắng cay.\",\"local_images\":[\"images/poem_2034_img_0.webp\"]},{\"id\":2033,\"title\":\"Thời Gian Còn Lại Những Gì\",\"date\":\"2026-08-11T13:37:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Thời gian còn lại những gì\\nSau cơn mưa với tình si muộn màng\\nChỉ còn vạt nắng gắt gỏng tan\\nVương trên lối cũ ngập tràn rêu phong.\\n\\nTa về nhặt chút sương trong\\nÉp vào trang sách giữ lòng bình yên\\nTrả người hết những ưu phiền\\nTrả tình xa vắng về miền hư vô.\\n\\nĐời người như những vần thơ\\nTrôi qua ghềnh thác đến bờ lặng thầm\\nMưa tan khép lại giọt trầm\\nMới hay buông bỏ... nghìn năm nhẹ nhàng.\",\"local_images\":[\"images/poem_2033_img_0.webp\"]},{\"id\":2032,\"title\":\"Em Nhớ Kỷ Niệm Xưa Nhiều Không\",\"date\":\"2026-08-11T13:36:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Em nhớ kỷ niệm xưa nhiều không?\\nKhi gió đông qua, nắng nhạt hồng.\\nChiều nghiêng vạt vắng bên hiên cũ,\\nNhặt chút hương xa gửi khoảng trống.\\n\\nĐường xưa chung lối rải heo may,\\nNhớ ánh mắt ai trao đong đầy.\\nNgón tay đan vội thời nông nổi,\\nGiờ hóa chiêm bao thoảng gió bay.\\n\\nTa hỏi lòng ta giữa giông bão,\\nTình cũ còn vương chốn chênh chao?\\nMấy mùa hoa nở rồi hoa giấu,\\nMột khoảng trời riêng... sâu thật sâu.\\n\\nChắc giờ bên ấy mùa đang chuyển,\\nEm có còn giữ vệt nắng hồng?\\nHay đã gửi trao niềm thương nhớ,\\nCho người đến sau... ngát mênh mông?\",\"local_images\":[\"images/poem_2032_img_0.webp\"]},{\"id\":2031,\"title\":\"Gánh Lưng Mẹ Vẫn Gầy Còm\",\"date\":\"2026-08-11T13:35:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Gánh lưng mẹ vẫn gầy còm,\\nSuốt đời nương tựa, đỡ con vào lòng.\\nTấm thân cha thật mỏng manh,\\nNắng mưa sương gió chỉ còn gầy trơ.\\n\\nNgày thơ con hỏi một lời:\\n\\\"Sao cha mẹ chẳng nghỉ ngơi đôi hồi?\\\"\\nMẹ cười, vuốt tóc con tôi:\\n\\\"Nhìn con khôn lớn... thế rồi niềm vui!\\\"\\n\\nGiờ đây con đã trưởng thành,\\nĐi qua giông bão mới tỏ lòng người.\\nXót xa nhìn tóc điểm sương,\\nBao năm cha mẹ đoạn trường vì con.\\n\\nCầu mong giông bão ngàn xa,\\nTrả bình yên lại cho nhà tôi vui.\\nĐổi bằng đánh cược đời con,\\nMong cha mẹ sống mãi trọn an yên.\",\"local_images\":[\"images/poem_2031_img_0.webp\"]},{\"id\":2030,\"title\":\"Sợ Ta Quên Khi Ta Già Yếu\",\"date\":\"2026-08-11T13:34:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Sợ ta quên khi ta già yếu,\\nTrọn vẹn tình yêu với nước non.\\nDẫu cho mái tóc chẳng còn xanh,\\nMáu đỏ trong tim vẫn sắt son.\\n\\nDẫu mắt thôi tinh, chân mỏi gối,\\nKý ức thời gian có nhạt mờ,\\nHồn ta vẫn hướng về sông núi,\\nGiữ trọn lời thề tự thuở xưa.\\n\\nĐất mẹ bao la ngàn thế hệ,\\nNuôi ta khôn lớn giữa bão giật.\\nMai này nằm xuống lòng đất mẹ,\\nVẫn hóa phù sa giữ đất trời!\",\"local_images\":[\"images/poem_2030_img_0.webp\"]},{\"id\":2029,\"title\":\"Mười Năm Đô Hộ Giặc Tàu\",\"date\":\"2026-08-11T13:33:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Mười năm đô hộ giặc Tàu,\\nTrăm năm nô lệ bọn Tây bán cầu.\\nMáu rơi nhuộm đỏ sông sâu,\\nMà lòng dân Việt dời đâu chí bền.\\n\\nTừ Nam Quan đến Cà Mau,\\nLời thề giữ nước dạt dào ngàn năm.\\nDẫu qua gông cùm tối tăm,\\nBình minh vẫn sáng dội vang núi sông.\\n\\nNgẩng đầu đứng dậy hiên ngang,\\nĐập tan xiềng xích, mở trang sử hồng.\\nTrả lại gấm vóc non sông,\\nCho con cháu mãi sống trong thanh bình!\",\"local_images\":[\"images/poem_2029_img_0.webp\"]},{\"id\":2028,\"title\":\"Dặn Rồi Hôm Ấy Đừng Mơ\",\"date\":\"2026-08-11T13:32:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Dặn rồi hôm ấy đừng mơ,\\nKhông nghe, rinh hết dại khờ thế gian.\\nTrút gom vạt nắng chiều tàn,\\nMang về giấu kín trong ngàn xót xa.\\n\\nNgười ta đi giữa gấm hoa,\\nRiêng mình nhặt mảnh tình qua bên đường.\\nĐêm nay giật mình ngát hương,\\nMới hay ôm trọn đau thương một đời.\\n\\nTrách ai nông nổi ham vui,\\nHay trách lòng mình ngậm ngùi nỡ thương?\\nRượu vơi chốn cũ phong sương,\\nĐành ôm giọt lệ soi đường người đi...\",\"local_images\":[\"images/poem_2028_img_0.webp\"]},{\"id\":2027,\"title\":\"Trời Cao Ba Trượng\",\"date\":\"2026-08-11T13:31:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Trời cao ba trượng\\nNước rộng ba tấc\\nXoạc chân đập nước\\nHết cả đất trời.\\n\\nCười vang một tiếng giữa đời\\nTay ôm sóng dữ, chân dời mây xanh.\\nNgông gieo vạt nắng ngút ngàn\\nRót ly rượu đắng trút ngàn sầu thương.\\n\\nNgẩng đầu rẽ lối phong sương\\nMặc cho dông bão coi thường dại khờ.\\nNgờ đâu giữa cõi mộng mơ\\nTa cùng trần thế làm thơ nối vần!\",\"local_images\":[\"images/poem_2027_img_0.webp\"]},{\"id\":2026,\"title\":\"Vườn Tôi Cây Lá Bình Yên\",\"date\":\"2026-08-11T13:30:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Vườn tôi cây lá bình yên\\nSương rơi nhè nhẹ ướt hiên nhà nàng\\nThu sang tô lá thêm vàng\\nNghe mây ngập ngừng chầm chậm ghé sang.\\n\\nNhành hoa trước ngõ khẽ lay\\nĐưa hương dìu dịu đong đầy khoảng không\\nChiều buông nghiêng vạt nắng hồng\\nNgồi gom nhung nhớ giấu vào trong thơ.\\n\\nBình yên một cõi mộng mơ\\nThời gian lắng lại như chờ đợi ai\\nBâng khuâng bước ngập ngừng dài\\nGiữ riêng chút tình chẳng phai theo mùa...\",\"local_images\":[\"images/poem_2026_img_0.webp\"]},{\"id\":2025,\"title\":\"Hỏi Đêm Trăng Sao Màu Nắng Chẳng Giữ\",\"date\":\"2026-08-11T13:29:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Hỏi đêm trăng sao màu nắng chẳng giữ\\nHỏi trăng vàng sao gió chẳng mang theo\\nĐể lại ta với khoảng lặng bọt bèo\\nNgồi ôm lấy bóng chiều rơi muộn màng.\\n\\nĐêm tịch mịch rải vệt mờ hoang vắng\\nTrăng trên cao đâu thấu nỗi lòng này\\nCơn gió thoảng lay cành chao hoa lá\\nChuốc thêm chốn mộng mị, thoáng cuồng say.\\n\\nTa nhặt lại từng mảnh tình vụn vỡ\\nThả theo dòng trôi dạt cõi hư vô\\nHỏi mây xám, hỏi ngàn dâu xanh ngắt\\nĐến bao giờ tim mới hết long đong?\",\"local_images\":[\"images/poem_2025_img_0.webp\"]},{\"id\":2024,\"title\":\"Một Chén Cho Người\",\"date\":\"2026-08-11T13:28:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Một chén cho người\\nMười năm kia đã hóa hư không\\nMột chén cho ta\\nGiấc mộng tan hòa cùng phôi pha\\n\\nRượu còn cay ta say hoài nhân thế...\\nThêm chén nữa rót trăng tàn dĩ vãng\\nCười cuồng ngông giữa vạt nắng tàn chiều\\nHỏi thế gian đời có được bao nhiêu\\n\\nMà trôi mãi giữa trăm điều được mất?\\nNgười ngoảnh mặt, lối xưa giờ xa tắp\\nTa ngoảnh nhìn, tóc đã chớm màu sương\\nLy rượu đắng chuốc trọn kiếp tha phương\\n\\nCạn sầu tủi, nghiêng sương mờ cõi mộng.\\nThôi bước tiếp giữa lòng đời mênh mông\\nGiữ chút tình làm hành trang dại khờ...\",\"local_images\":[\"images/poem_2024_img_0.webp\"]},{\"id\":2023,\"title\":\"Tôi Hỏi Gió Hương Hoa Còn Giữ Mãi\",\"date\":\"2026-08-11T13:27:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Tôi hỏi gió hương hoa còn giữ mãi\\nTôi hỏi sóng thuyền không neo có xa bờ\\nNhững vầng trăng có còn gieo thành thơ\\nHay tan biến giữa muôn ngàn dấu vết?\\n\\nTôi hỏi nắng ngày dài sao chẳng hết\\nĐể giọt sương đọng lại chút tình vương\\nTôi hỏi người câu hẹn góc phố thường\\nGiờ có phải theo chiều thu hóa xám?\\n\\nGió lặng lẽ thổi qua triền ký ức\\nSóng thì thầm vỗ nhẹ bến bình yên\\nTrăng dẫu khuyết vẫn gieo vạt muộn phiền\\nLên từng dòng thơ tôi vừa viết vội...\\n\\nTrả lời tôi, khoảng trời xanh không nói\\nChỉ mơ hồ một nhánh dạ hương bay.\",\"local_images\":[\"images/poem_2023_img_0.webp\"]},{\"id\":2022,\"title\":\"Giấc Mơ Em Nó Viết Vội Trong Tâm Hồn Nào Biết\",\"date\":\"2026-08-11T13:26:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Giấc mơ em nó viết vội trong tâm hồn nào biết\\nGiọt nước mắt kia rơi vội trên những lối đi về\\nCòn ai em hỡi tay nắm trong ngày dài giá lạnh\\nTay không tay, chân lẻ bước trong những đêm dài\\n\\nTình kia nay đã tan vỡ khi hai người quay lối\\nMột niềm đau một nỗi sầu ai thấu...\\nĐoạn đường xưa nay khuất bóng chỉ còn làn sương lạnh\\nKỷ niệm xưa theo gió thoảng vỡ tan giữa mây trời.\\n\\nLời thề xưa như lớp sóng cuốn trôi theo dòng nước\\nTrả lại em câu giã biệt, trả lại tiếng thở dài.\\nĐèn đường khuya soi chiếc bóng đơn côi nơi góc nhỏ\\nNgoảnh mặt đi ngăn khóe mắt chớ rơi vạt lệ tràn.\\n\\nGhì niềm riêng gom góp lại, giấu sâu trong góc khuất\\nNhủ lòng qua mùa bão giật... mai đời sẽ bình yên.\",\"local_images\":[\"images/poem_2022_img_0.webp\"]},{\"id\":2021,\"title\":\"Con Mẹ Trở Về Ngày Khải Hoàn\",\"date\":\"2026-08-11T13:25:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Con mẹ trở về ngày khải hoàn,\\nNắm xương tro cốt còn nặng mang.\\nCờ đỏ tung bay rợp góc trời,\\nSao lòng mẹ lạnh, lệ hai hàng.\\n\\nMẹ đón con về trong lặng lẽ,\\nLời hứa năm xưa đã trọn tròn.\\nĐất nước thanh bình, ngời sắc thắm,\\nĐổi bằng xương máu tuổi hoài xuân.\\n\\nÔm chặt bình vôi, ghì mảnh cốt,\\nNhư ngày thơ dại ẵm trên tay.\\nCon đi giữ lấy từng tấc đất,\\nMẹ ở lại ôm trọn đắng cay.\\n\\nThôi ngủ đi con, đất mẹ lành,\\nSông núi ngàn năm ngát màu xanh.\\nKhải hoàn vinh quang tràn lối cũ,\\nMẹ gọi tên con giữa thanh bình...\",\"local_images\":[\"images/poem_2021_img_0.webp\"]},{\"id\":2020,\"title\":\"Nhân Sinh Một Ván Cờ Hòa\",\"date\":\"2026-08-11T13:24:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Nhân sinh một ván cờ hòa,\\nTuế hoa vọng nguyệt xót xa trong lòng.\\nTrăm năm đục đục trong trong,\\nTrôi theo nước chảy qua dòng thời gian.\\n\\nChiều buông nghiêng vạt nắng tàn,\\nTrắng tay ngoảnh lại trần gian lặng trầm.\\nChuốc chén rượu đắng, tơ trầm,\\nĐôi dòng thơ cũ nghìn năm một đời.\\n\\nNgẩng đầu nhìn bóng trăng rơi,\\nMấy vinh mấy nhục... buông lơi nụ cười.\",\"local_images\":[\"images/poem_2020_img_0.webp\"]},{\"id\":2019,\"title\":\"Mười Năm Trở Lại Dòng Sông Ấy\",\"date\":\"2026-08-11T13:23:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Mười năm trở lại dòng sông ấy\\nKhói trắng hương bay tỏa mịt mờ\\nCon đường ấy bao lần tôi dừng lại\\nNhìn bến quê xưa ngỡ một giấc mơ.\\n\\nDòng nước ngược xuôi trôi niềm nhớ\\nNgón tay ai vuốt vệt thời gian\\nMười năm xa cách bên hoài niệm\\nGiữa chốn phồn hoa lắm đoạn tràng.\\n\\nCỏ xanh vẫn phủ triền bờ cũ\\nMà người năm ấy đã xa xôi\\nTôi đứng ôm thầm cơn gió muộn\\nThả chút hương xưa lặng lẽ rơi...\",\"local_images\":[\"images/poem_2019_img_0.webp\"]},{\"id\":2018,\"title\":\"Em Ơi Em Ta Còn Gì Với Nhau\",\"date\":\"2026-08-11T13:22:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Em hỡi em, ta còn gì cho nhau?\\nLà nhung nhớ hay những điều vụn vỡ?\\nLà chút bình yên sau tro tàn còn sót,\\nHay muộn phiền quẩn quanh miền ký ức?\\n\\nTa thấy lòng như lửa đốt, rã rời,\\nGiữa đêm lạnh chẳng vòng tay ấm áp.\\nNhững giấc mơ trôi dạt tận phương nào,\\nTuổi thanh xuân – một lần từng ảo vọng.\\n\\nÁm ảnh theo ta đến tận chiều tàn,\\nKhóe mắt cay, lòng chẳng còn bình lặng.\\nChỉ muốn say, để mãi mãi ngủ quên,\\nDẫu bước gần, sao vẫn xa trọn kiếp...\",\"local_images\":[\"images/poem_2018_img_0.webp\"]},{\"id\":2017,\"title\":\"Dạo Này Em Thấy Bận Ghê\",\"date\":\"2026-08-11T13:21:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Dạo này em thấy bận ghê,\\nBận ăn, bận sống mà quên giờ yêu tôi.\\nBận trông lên những ngọn đồi,\\nHoa của kẻ khóc, kẻ cười thế gian.\\n\\nBận đi qua những miên man,\\nNhặt gom chút nắng nhẹ nhàng phai phôi.\\nBận nghe tiếng sóng đầy vơi,\\nQuên luôn góc nhỏ có người đợi mong.\\n\\nThôi thì em cứ thong dong,\\nGiữa đời xuôi ngược chất chồng bão giông\\nTôi ngồi thương thuở đi cùng,\\nGiữ riêng chút ấm lặng thầm... cho em.\",\"local_images\":[\"images/poem_2017_img_0.webp\"]},{\"id\":2016,\"title\":\"Tôi Nhặt Mùa Thu Rơi Trên Lá\",\"date\":\"2026-08-11T13:20:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn\",\"content_text\":\"Tôi nhặt mùa thu rơi trên lá\\nSắc vàng e ấp, lá vàng phai.\\nHình như cơn gió vừa qua ngõ,\\nThổi nhẹ heo may buông thở dài.\\n\\nNhặt chút hương xưa vương lối cũ,\\nNhặt miền nhớ lặng giấu tim ai.\\nChiều buông nghiêng bóng trên triền vắng,\\nThơ thẩn người đi buổi sớm mai.\\n\\nThu giữ giùm ta bao kỷ niệm,\\nMột thời ngơ ngác giữa chiêm bao.\\nLòng như tờ giấy quen nét mực,\\nThả giấc mơ riêng giữa cõi nào...\",\"local_images\":[\"images/poem_2016_img_0.webp\"]},{\"id\":2015,\"title\":\"Sương Mờ Ôm Góc Núi Quanh Co\",\"date\":\"2026-08-11T13:19:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Sương mờ ôm góc núi quanh co,\\nTiều phu dưới nắng, cỏ che mờ.\\nKhói bếp ai nhóm miền tịch mịch,\\nThả chút u hoài vương ý thơ...\\n\\nGió lạnh qua rặng cây xơ xác,\\nLối cũ tìm đâu bước chân xưa?\\nRượu nồng một chén mong tri kỷ,\\nNghe giọt thời gian lặng lẽ thừa.\",\"local_images\":[\"images/poem_2015_img_0.webp\"]},{\"id\":2014,\"title\":\"Nắng Chớm Tắt Cuối Con Đường Ngõ Nhỏ\",\"date\":\"2026-08-11T13:18:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Nắng chớm tắt cuối con đường ngõ nhỏ\\nTôi tìm về cũng đây đó bao lần\\nLòng bâng khuâng... nghe bước chân ngập ngừng,\\nBóng chiều buông trên mái rêu xám cũ.\\n\\nKhói lam chiều vương nhẹ lối quen xưa,\\nGió thì thầm câu chuyện thời thơ dại.\\nMới ngày nào góc phố còn ngơ ngác,\\nGiờ ngoảnh lại, thanh xuân đã muộn màng.\\n\\nCánh hoa rơi lặng lẽ bên khoảng sân,\\nNhặt kỷ niệm giấu vào trong nỗi nhớ.\\nCon đường cũ vẫn nằm yên ở đó,\\nChỉ người về... mang nặng tuổi thời gian.\",\"local_images\":[\"images/poem_2014_img_0.webp\"]},{\"id\":2013,\"title\":\"Tôi Không Biết Nắng Có Màu Xanh\",\"date\":\"2026-08-11T13:17:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Tôi không biết nắng có màu xanh\\nKhi mưa rào mang theo bao nồng ấm\\nNhớ thương xưa vẫn ngọt ngào, sâu đậm\\nTrôi lững lờ theo từng nhịp thời gian.\\n\\nGió heo may khe khẽ thổi qua làng,\\nGửi vần thơ vào khoảng trời lặng lẽ.\\nBao kỷ niệm của một thời tuổi trẻ,\\nChợt đong đầy trong ký ức hôm nay.\\n\\nMưa tan rồi, mây lại kéo về đây,\\nChút hương cũ vương trên bờ vai nhỏ.\\nCon đường xưa dẫu muôn trùng gian khó,\\nVẫn vẹn nguyên một khoảng trời bình yên.\",\"local_images\":[\"images/poem_2013_img_0.webp\"]},{\"id\":2012,\"title\":\"Có Những Con Đường\",\"date\":\"2026-08-11T13:16:44.000Z\",\"date_formatted\":\"11 tháng 8, 2026\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Có những con đường\\nVà có một giấc mơ\\nCó những dại khờ\\nNằm lại thời xa vắng.\\n\\nCó những chiều thầm lặng\\nNgồi đếm giọt mưa rơi\\nGiấc mơ bay thật xa,\\nĐong đầy bao nỗi nhớ.\\n\\nĐường đời muôn lối mở\\nTa bước giữa chênh chao\\nNhặt chút thơ ngày cũ\\nGửi vào cõi mộng nao...\\n\\nThương từng vệt chiêm bao\\nKhắc trên tàn nắng hạ\\nQuên - nhớ giữa người lạ\\nTa về với riêng ta.\",\"local_images\":[\"images/poem_2012_img_0.webp\"]},{\"id\":2011,\"title\":\"Khi Cánh Hoa Cuối Cùng Nở\",\"date\":\"2026-07-21T04:13:41.985Z\",\"date_formatted\":\"21 tháng 7, 2026\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Khi cánh hoa cuối cùng nở\\nLá biết cây sẽ tàn\\nKhi hạ vội vàng sang\\nMùa đông vừa chợt đến\\n\\nTa thấy đời gian nan\\nViết vội vàng hạnh phúc\\nGom vần thơ ngả nghiêng\\nTrải giữa lòng thực đục.\\n\\nĐường vạn lý thênh thang\\nBụi mờ lên mắt trẻ\\nGặp nhau chốn nhân gian\\nNíu làm sao tay nhẹ?\\n\\nChờ vạt nắng cuối chiều\\nHong mảnh hồn buốt giá\\nNgười đi qua thương yêu\\nĐã thành người xa lạ.\\n\\nMai này hoa lại nở\\nLá lại xanh trên cành\\nChỉ có nỗi giông bão\\nĐã nằm yên khép manh.\",\"local_images\":[\"images/poem_2011_img_0.webp\"]},{\"id\":2010,\"title\":\"Mười Năm Chưa Lần Gặp\",\"date\":\"2026-07-20T12:43:41\",\"date_formatted\":\"20 tháng 7, 2026\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Mười năm chưa lần gặp\\nSao ta vẫn đợi chờ\\nMột bóng hình đã lỡ\\nChưa gặp lại trong mơ\\n\\nMọi thứ đã phai mờ\\nChỉ in hằn lên cát\\nDấu chân kẻ tình si\\nTừng bước đi từng đi\\n\\nLuẩn quẩn trong tâm trí\\nKẻ si chẳng bóng hình\\nNhân gian thật vô tình\\nĐến hay đi chẳng tỏ...\",\"local_images\":[\"images/poem_2010_img_0.webp\"]},{\"id\":2009,\"title\":\"Yêu Em Tóc Đã Bạc Rồi\",\"date\":\"2026-07-20T12:43:00\",\"date_formatted\":\"20 tháng 7, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Yêu em tóc đã bạc rồi\\nTrái tim không biết nói lời mộng mơ\\nNgày ngày chỉ biết trông chờ\\nTrăng lên gửi áng vầng thơ tới nàng\\n\\nBóng trăng in khuyết gối nàng\\nGió xuân vội khẽ thì thầm bên tai\\nHai ta xa tận góc trời\\nNhờ lời của gió gửi lời yêu thương\\n\\nDặm trường dạo bước nhớ thương\\nXa xôi muôn dặm còn thương nhớ về\",\"local_images\":[\"images/poem_2009_img_0.webp\"]},{\"id\":2008,\"title\":\"Tôi Đi Giữa Chốn Nhân Gian\",\"date\":\"2026-07-20T12:36:00\",\"date_formatted\":\"20 tháng 7, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Tôi đi giữa chốn nhân gian\\nMuốn mang gửi lại bên hàng dương xanh\\nOanh vàng cất tiếng líu lo\\nMộng vàng chưa tỏ, nắng vàng vội phai\\n\\nHỡi ai gieo chút nhớ thương\\nCòn vương sợi nhớ bên hàng thông reo\\nTrăng treo trong gió dỗi hờn\\nGieo chi một nửa vấn vương tơ lòng\\n\\nHỏi rằng người có nhớ không\\nÁnh hồng rẽ nước chia đôi\\nNửa mang thương nhớ trôi theo ngược dòng\\nBóng hồng tựa nhánh liễu đào\\nGieo tương tư ấy vào trong cõi trần\",\"local_images\":[\"images/poem_2008_img_0.webp\"]},{\"id\":2007,\"title\":\"Lững Lờ Giữa Thế Gian Này\",\"date\":\"2026-07-18T20:52:30\",\"date_formatted\":\"18 tháng 7, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Lững lờ giữa chốn gian trần,\\nGửi trao kỷ niệm bên phần dương liễu.\\nTiếng chim vang đượm khúc chiều,\\nGiấc mơ vàng úa, nắng xiêu mịt mờ.\\n\\nAi gieo chi sợi thương nhớ,\\nThông reo gió bấc, trăng treo bên trời.\\nRối bời một dải tơ đời,\\nNửa lòng vương vấn, nửa lời thở than.\\n\\nNgười ơi, có nhớ chăng ngàn?\\nDòng sông ánh hồng, đôi hàng mộng mơ.\\nThương nhớ trôi bến bờ xa,\\nBóng hồng đào liễu, mênh mông tình si.\",\"local_images\":[\"images/poem_2007_img_0.webp\"]},{\"id\":2006,\"title\":\"Gió Đông Heo Hắt Bên Thềm\",\"date\":\"2026-07-18T20:52:00\",\"date_formatted\":\"18 tháng 7, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Gió đông heo hắt bên thềm\\nRêu phong cảnh cũ, sau thềm lá rơi\\nPhong sương tuyết phủ ngập trời\\nBếp nhỏ hiu hắt đưa người về đâu\\nGiọt sương pha với giọt sầu\\nÁo nâu xếp lại, bạc màu nắng mưa\\nVườn xưa vắng bóng người xưa\\nHàng cau đứng lặng như vừa ngóng ai\\nKhói trầm lãng đãng sương mai\\nHương quen phảng phất, trang đài bỏ không.\",\"local_images\":[\"images/poem_2006_img_0.webp\"]},{\"id\":2005,\"title\":\"Bếp Nhà Lửa Vẫn Nhóm Mỗi Đêm\",\"date\":\"2026-07-18T20:49:30\",\"date_formatted\":\"18 tháng 7, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Bếp nhà lửa vẫn nhóm mỗi đêm\\nCủi hồng vẫn cháy, tro tàn vẫn rơi\\nNgười ngồi hong lại khoảng đời\\nMà tim lạnh giá như thời lập đông.\\n\\nBình hoa nằm ở góc phòng\\nVẹn nguyên không vết rạn ngoài\\nNhưng nguồn nước bên trong đành chịu lỗi\\nChẳng thể nuôi nổi một nhành hoa phai\\n\\nHai chiếc lá như chung một cội\\nNương vào nhau qua giông gió cuộc đời\\nNhưng nhựa sống bên trong đã mỏi\\nChẳng buồn xanh, cũng chẳng muốn rơi.\",\"local_images\":[\"images/poem_2005_img_0.webp\"]},{\"id\":2004,\"title\":\"Một Đời Nhớ Nhớ Thương Thương\",\"date\":\"2026-07-18T20:49:00\",\"date_formatted\":\"18 tháng 7, 2026\",\"genre\":\"Lục bát\",\"content_text\":\"Một đời nhớ nhớ thương thương\\nCười vui thì ít mà nhớ thương thì nhiều\\nHoàng hôn bớt ráng bóng chiều\\nTương tư trải cạnh một chiều yêu đương\",\"local_images\":[\"images/poem_2004_img_0.webp\"]},{\"id\":2002,\"title\":\"Cố Gắng Trăm Lần... Vẫn Mất Nhau\",\"date\":\"2026-07-18T20:47:00\",\"date_formatted\":\"18 tháng 7, 2026\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Cố gắng chăm vườn, vườn vẫn sâu,\\nCố gắng không sầu, sầu vẫn vương.\\nCố gắng không khóc, lệ vẫn tuôn,\\nCố gắng quên người, dạ vẫn thương.\\n\\nCố gắng gượng cười, môi héo hắt,\\nCố gắng thản nhiên, lòng vẫn đau.\\nCố gắng tìm quên, sầu lại thắt,\\nCố gắng trăm lần, vẫn mất nhau.\",\"local_images\":[\"images/poem_2002_img_0.webp\"]},{\"id\":2001,\"title\":\"Chôn Vào Hư Không\",\"date\":\"2026-07-18T20:46:30\",\"date_formatted\":\"18 tháng 7, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Ngày ấy,\\nTre vẫn xanh, gió vẫn reo\\nNhưng bình yên đã không còn nữa\\nChim vẫn hót, mây vẫn bay\\nTay đã không còn nắm\\n\\nVà rồi,\\nNgười mỉm cười, chân vẫn bước\\nGió cũng im, lá đã ngừng\\nSóng ngoài xa đã thôi rì rào\\nLòng ta đã chôn vào hư không!\",\"local_images\":[\"images/poem_2001_img_0.webp\"]},{\"id\":2000,\"title\":\"Gần Gang Tấc... Cách Trùng Khơi\",\"date\":\"2026-07-18T20:46:00\",\"date_formatted\":\"18 tháng 7, 2026\",\"genre\":\"Tự do\",\"content_text\":\"Tôi đã dốc thanh xuân qua trăm ngả,\\nNhìn hoa tàn lặng phủ lối xưa,\\nNhìn nắng sớm vừa chạm bên trời,\\nMà chẳng thể sưởi tan hồ băng giá.\\n\\nCứ ngỡ chung thuyền, cùng vượt sóng,\\nNào hay lạc giữa cõi dửng dưng.\\nLửa nơi vách lòng ta âm thầm đỏ rực,\\nNgười lặng im, mặc kệ hóa tro than.\\n\\nGần gang tấc... mà cách trùng khơi.\",\"local_images\":[\"images/poem_2000_img_0.webp\"]},{\"id\":1353,\"title\":\"Người mơ về chốn xa xôi\",\"date\":\"2025-09-05T14:01:48\",\"date_formatted\":\"5 tháng 9, 2025\",\"genre\":\"Lục bát\",\"content_text\":\"Người mơ về chốn xa xôi\\nTa chỉ thèm một mái nhà bình yên\\nNgười vui với những muộn phiền\\nTa gom nhặt chút an nhiên cho mình!\\nNgười nhìn bằng ánh bình minh\\nThấy danh vọng, thấy cuộc tình hơn thua\\nTa nhìn đời lúc đổ mưa\\nThấy vai gầy gánh nắng trưa mệt nhoài.\\nCâu chuyện cứ mỗi ngày dài\\nMà tâm hồn lại cách hai phương trời\\nNgười buông những tiếng buông lơi\\nTa nghe chỉ thấy một đời lặng câm.\\nNhiều khi cay đắng âm thầm\\nMuốn buông tay để lạc lầm một phen\\nChẳng chung một giấc mơ hồng\\nChẳng chung lối bước, giấc nồng đêm say.\",\"local_images\":[\"images/poem_1353_img_0.webp\"]},{\"id\":1338,\"title\":\"Phiền muộn chỉ là một giọt nước\",\"date\":\"2025-08-28T09:10:28\",\"date_formatted\":\"28 tháng 8, 2025\",\"genre\":\"Tự do\",\"content_text\":\"Phiền muộn chỉ là một giọt nước, nhưng ta lại đong đầy cả đại dương.\\nCô đơn chỉ là làn khói mỏng, nhưng lại che mờ cả nhân gian.\\nNỗi buồn là hạt cát, lấp đầy cả đại dương.\\nMuốn nhận tia nắng ấm, lại phải hứng chịu cả cơn mưa.\",\"local_images\":[\"images/poem_1338_img_0.webp\"]},{\"id\":1335,\"title\":\"Em thấy gì trong buổi chiều lạc lõng\",\"date\":\"2025-08-28T09:07:49\",\"date_formatted\":\"28 tháng 8, 2025\",\"genre\":\"Tự do\",\"content_text\":\"Em thấy gì trong buổi chiều lạc lõng!\\nĐôi vai gầy không cõng hết cô đơn.\\nBóng hoàng hôn in dấu chân lạc mất,\\nCõi cô đơn dài đến cạn ưu phiền.\",\"local_images\":[\"images/poem_1335_img_0.webp\"]},{\"id\":1332,\"title\":\"Có những nơi gọi là nhà\",\"date\":\"2025-08-28T09:03:33\",\"date_formatted\":\"28 tháng 8, 2025\",\"genre\":\"Lục bát\",\"content_text\":\"Có những nơi gọi là nhà\\nCó những phút giây gọi là hạnh phúc\\nKhông thiên đường cũng chẳng là địa ngục\\nNơi chôn vùi những hạnh phúc từng qua...\",\"local_images\":[\"images/poem_1332_img_0.webp\"]},{\"id\":1329,\"title\":\"Nắng rớt bên thềm nhà\",\"date\":\"2025-08-28T08:58:51\",\"date_formatted\":\"28 tháng 8, 2025\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Nắng rớt bên thềm nhà\\nMột cánh hoa tàn phai\\nGió reo trên ngọn cỏ\\nHoàng hôn của ngày mai!\\n\\n\\n\\n\\n\\nChiều xuống nhẹ như kéo\\nSau những tháng ngày dài\\nĐầy sương và sỏi đá\\nƯớt đẫm cả tương lai\\n\\n\\n\\n\\n\\nSau cùng chỉ còn có\\nĐêm và bóng hình ai\\nIn dài trên cát trắng\\nMột nốt trầm ngân dài\",\"local_images\":[\"images/poem_1329_img_0.webp\"]},{\"id\":1308,\"title\":\"Anh từng sống giữa hạ vàng nắng gắt\",\"date\":\"2025-04-16T12:01:28\",\"date_formatted\":\"16 tháng 4, 2025\",\"genre\":\"Tự do\",\"content_text\":\"Anh từng sống giữa hạ vàng nắng gắt,\\nLòng cô đơn như phố vắng chiều tà.\\nBao năm tháng, tim khô cằn sỏi đá,\\nChờ một người – như nắng đợi mưa sa!\\n\\n\\n\\n\\n\\n\\nRồi em đến, nhẹ nhàng như mây trắng,\\nMắt em cười – anh thấy hạ dịu êm.\\nCơn mưa rào đổ qua tim thầm lặng,\\nTình yêu về, xanh mát cả trời đêm.\",\"local_images\":[\"images/poem_1308_img_0.webp\"]},{\"id\":1302,\"title\":\"Ra chợ tìm mua một chút yên\",\"date\":\"2025-04-16T11:36:24\",\"date_formatted\":\"16 tháng 4, 2025\",\"genre\":\"Thất ngôn\",\"content_text\":\"Ra chợ tìm mua một chút yên,\\nTiện tay buông bán thúng muộn phiền.\\nGánh gồng lảo đảo chân xiêu vẹo,\\nĐổi chút an nhiên – chẳng bạc tiền!\\n\\nPhố chợ đông người, toàn bán lo,\\nAi ai cũng chất muộn phiền to.\\nBình yên đỏ mắt hoài không thấy,\\nThúng buồn nằm đó vẫn còn to.\\n\\nRa chợ tìm mua thuở dại khờ,\\nTuổi thơ ngây ngốc lắm mộng mơ.\\nTìm hoài chẳng thấy – lòng tiếc nuối,\\nĐành bước trọn đời mãi đợi chờ.\\n\\nCó hay ai bán giữa trần ai,\\nVài cân hạnh phúc, chút mê say?\\nNgười mua xếp hàng dài chen lấn,\\nHạnh phúc lang thang, chẳng đến tay.\\n\\nSao thế? Phố chợ rộn ràng vui,\\nTỷ điều lợi lộc, vạn sầu nguôi.\\nCho đi toàn những điều không nhận,\\nMong mãi điều cần chẳng ai vui.\",\"local_images\":[\"images/poem_1302_img_0.webp\"]},{\"id\":1298,\"title\":\"Thôi đừng trách mùa thu không còn lá\",\"date\":\"2025-04-04T14:39:32\",\"date_formatted\":\"4 tháng 4, 2025\",\"genre\":\"Tự do\",\"content_text\":\"Thôi đừng trách mùa thu không còn lá,\\nNắng bớt vàng hay... đã nhạt phai!\\nNắng đã đến, đã đi và đã tắt\\nSóng vỗ bờ, thuyền mãi còn khơi xa!\\nHoa đã nở đã tàn nào ai biết\\nHay chỉ loài ong bướm mới hay\\nSớm mai này không hoàng hôn nắng cháy\\nChỉ còn mình loài hoa dại bên đường\",\"local_images\":[\"images/poem_1298_img_0.webp\"]},{\"id\":1294,\"title\":\"Bản ngã giăng lối trong tim\",\"date\":\"2025-04-04T14:36:38\",\"date_formatted\":\"4 tháng 4, 2025\",\"genre\":\"Tự do\",\"content_text\":\"Bản ngã giăng lối trong tim,\\nMê cung ảo ảnh, lời tự ngã vang vọng,\\nPhản chiếu những con đường riêng biệt,\\nẨn chứa muôn màu của đắng cay và ngọt bùi!\\n\\n\\n\\n\\n\\n\\nNhưng đâu đó, bên dưới lớp vỏ ảo,\\nChân ngã – linh hồn nguyên sơ chưa phai,\\nNhư mảnh đất êm ả chờ đón ánh sáng,\\nHòa vào giai điệu chân lý của vũ trụ.\\n\\n\\n\\n\\n\\n\\nGiữa những va chạm của tư duy và cảm xúc,\\nTa học cách buông bỏ những ràng buộc xa xăm,\\nĐể lắng nghe tiếng thở của sự tự do,\\nVà tìm thấy chính mình trong nhịp đập vĩnh hằng.\",\"local_images\":[\"images/poem_1294_img_0.webp\"]},{\"id\":1291,\"title\":\"Tôi tìm ai giữa bầu trời chen nắng\",\"date\":\"2025-04-04T14:31:18\",\"date_formatted\":\"4 tháng 4, 2025\",\"genre\":\"Tự do\",\"content_text\":\"Tôi tìm ai giữa bầu trời chen nắng,\\nAi tìm tôi giữa phố vắng đang mưa?\\nGió lặng lẽ gọi tên trong thoáng nhớ,\\nLá rơi đầy lòng có ngỡ như xưa!\\nChiều lặng lẽ nghiêng mình bên dốc cũ,\\nNgõ hoang buồn mưa phủ lối tôi đi.\\nBước chân nhỏ lạc vào miền ký ức,\\nTay hững hờ níu bóng dáng xuân thì.\\nNgười còn đó hay đã thành sương khói?\\nTôi mải tìm mà chẳng thấy dấu yêu.\\nGiữa nhân thế muôn ngàn dòng mắt vội,\\nAi đứng chờ trong hoang vắng cô liêu?\",\"local_images\":[\"images/poem_1291_img_0.webp\"]},{\"id\":1248,\"title\":\"Nhớ em, mưa hạ vội vã trôi\",\"date\":\"2024-04-09T15:43:36\",\"date_formatted\":\"9 tháng 4, 2024\",\"genre\":\"Tự do\",\"content_text\":\"Nhớ em, mưa hạ vội vã trôi\\nNắng lên, hoa nở chào ngày mới\\nSớm mai tươi, hồng hoa đưa lối\\nMong manh áo vải gió nhạt phai!\\n\\n\\n\\n\\n\\nYêu thương qua, say đắm rồi tỉnh giấc\\nChìm trong mơ, rồi lại thả tay lơi\\nRượu nồng cay, lệ đượm buồn vui\\nMộng mị say, hay tỉnh thực giữa đời?\",\"local_images\":[\"images/poem_1248_img_0.webp\"]},{\"id\":1245,\"title\":\"Ta nhớ em, cơn mưa rào trưa hè\",\"date\":\"2024-04-09T15:40:46\",\"date_formatted\":\"9 tháng 4, 2024\",\"genre\":\"Tự do\",\"content_text\":\"Ta nhớ em, cơn mưa rào trưa hè\\nNắng chợt đến và hoa chớm nở\\nBan mai xanh bên cánh hồng hoa\\nÁo ta ướt nhạt nhòa trong gió!\\n\\n\\n\\n\\n\\nTa đã yêu, đã say và đã tỉnh\\nĐã đắm chìm và cũng đã buông tay\\nMen rượu cay, mắt lệ ngắn dài\\nSay trong say hay tỉnh dài trong mộng!\",\"local_images\":[\"images/poem_1245_img_0.webp\"]},{\"id\":1241,\"title\":\"Thôi, ta hẹn nhau kiếp khác\",\"date\":\"2023-12-20T12:00:54\",\"date_formatted\":\"20 tháng 12, 2023\",\"genre\":\"Tự do\",\"content_text\":\"Thôi, ta hẹn nhau kiếp khác\\nDuyên với tình nay lỡ lạc mất rồi\\nMây cứ trôi và nước cứ chảy\\nHòn đá buồn, cây cũng vẫn cô đơn!\\nDòng suối nhỏ chỉ đưa thuyền ra biển lớn\\nMặc sóng, mặc gió, mặc tất cả\\nĐoạn đường giờ hai ngả chia đôi\\nBước cũng vội, lạc mất khúc tình si\",\"local_images\":[\"images/poem_1241_img_0.webp\"]},{\"id\":1231,\"title\":\"Hỏi rằng tôi đã quên chưa\",\"date\":\"2023-12-15T15:38:09\",\"date_formatted\":\"15 tháng 12, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Hỏi rằng tôi đã quên chưa?\\nTôi còn nhớ lắm, và thưa: rất buồn!\\nRèm thưa buông nhẹ hững hờ\\nKiêu sa ánh mắt chẳng là của tôi!\\n\\n\\n\\n\\n\\nKỷ niệm còn chút phôi phai?\\nTôi còn trong mộng với ai hỡi người!\\nBốn phương gió lộng tứ bề\\nMột thân cô độc hẹn thề với ai!\",\"local_images\":[\"images/poem_1231_img_0.webp\"]},{\"id\":1228,\"title\":\"Em ơi em có nghe\",\"date\":\"2023-12-15T15:34:54\",\"date_formatted\":\"15 tháng 12, 2023\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Em ơi em có nghe\\nNắng rớt bên hiên nhà\\nĐàn trẻ con ngân nga\\nNhững bài ca đón Tết!\\nMùa xuân vừa mới dệt\\nTấm áo mới mọi nơi\\nVẽ nên những nụ cười\\nTrên đôi môi hớn hở\\nLộc treo đầy khắp phố\\nHạnh phúc tràn vào nhà\\nChúc sức khỏe ông bà\\nGia đình luôn êm ấm\\nTrẻ em luôn vui tươi\\nHọc hành càng phấn khởi\\nCha mẹ luôn yêu đời\\nCông danh càng tấn tới\\nÔng bà luôn phơi phới\\nBạc đầu tới trăm tuổi\\nHạnh phúc tới mọi nơi\\nCùng đón mừng năm mới\",\"local_images\":[\"images/poem_1228_img_0.webp\"]},{\"id\":1225,\"title\":\"Người ta học cách nhớ thương\",\"date\":\"2023-12-15T15:30:49\",\"date_formatted\":\"15 tháng 12, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Người ta học cách nhớ thương\\nTôi đây học cách để quên một người\\nQuên trong ánh mắt nụ cười\\nTrong làn môi ấm, trong lời yêu thương!\\nTừng giây trong những đêm trường\\nUyên ương mộng đẹp khắp vườn hồng hoa\\nTương tư từ lúc xế tà\\nCanh ba đã điểm tiếng gà cũng say\\nSay trong cõi mộng một ngày\\nThế gian say cả vạn ngày mộng mơ\\nLàm sao quên đã tôn thờ\\nLàm sao vứt bỏ từng giờ yêu thương\\nLàm sao quên những con đường\\nLàm sao để trả yêu thương trở về\\nLàm sao để xóa não nề\\nLàm sao thoát khỏi u mê mộng tình\",\"local_images\":[\"images/poem_1225_img_0.webp\"]},{\"id\":1222,\"title\":\"Chim ơi chim đừng bay\",\"date\":\"2023-12-15T15:27:47\",\"date_formatted\":\"15 tháng 12, 2023\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Chim ơi chim đừng bay\\nĐậu bên cạnh hoa này\\nChờ trái chín đầy cành\\nMang khắp miền yêu thương!\\nGieo tương tư khắp chốn\\nLạc rớt hiên nhà nàng\\nHạt cây si vừa nở\\nGieo trong niềm nhớ thương\\nĐợi chờ lớn từng ngày\\nTrong từng giây còn nhớ\\nBóng hình của nàng thơ\\nMơ trong mơ cũng nhớ\\nSay trong say còn tỉnh\\nChợt vô tình gọi tên\",\"local_images\":[\"images/poem_1222_img_0.webp\"]},{\"id\":1219,\"title\":\"Chú chim nho nhỏ, chưa tỏ yêu thương\",\"date\":\"2023-12-15T15:21:21\",\"date_formatted\":\"15 tháng 12, 2023\",\"genre\":\"Tự do\",\"content_text\":\"Chú chim nho nhỏ, chưa tỏ yêu thương\\nĐậu trên cành hường, chờ tương tư đến\\nCánh hồng cũng mến, tỏa chút hương thơm\\nChim nhỏ vô tình, rớt trong tình nhỏ!\\n\\n\\n\\n\\n\\nChim có cánh to nhưng chẳng bay nhảy\\nCứ cạnh hồng nhỏ chờ gió thật to\\nChim giang cánh nhỏ cho gió đừng vào\\nThổi cánh hoa nào vội tàn đi mất\\n\\n\\n\\n\\n\\nTrông trời trông đất, trông tháng trông ngày\\nNhưng chẳng được may, hoa tàn phút chốc\\nChim nhỏ bỗng chốc, gốc hoa cạnh nằm\\nChờ xuân hoa đến, nảy mầm yêu đương\",\"local_images\":[\"images/poem_1219_img_0.webp\"]},{\"id\":1216,\"title\":\"Yêu em cho đến khi con tim ngừng đập\",\"date\":\"2023-12-15T15:17:46\",\"date_formatted\":\"15 tháng 12, 2023\",\"genre\":\"Tự do\",\"content_text\":\"Yêu em cho đến khi con tim ngừng đập\\nNước mắt kia ngừng rơi, lời yêu chẳng rõ thành lời\\nLòng anh se thắt lại cho nỗi nhớ đừng tan\\nYêu em trong muộn màng, vội vàng trong sầu lắng!\\nAnh say trong màu nắng em rải trên cát vàng\\nGục lên tàn cánh phượng, em vô tình đánh rơi\\nBiển xa khơi nhớ bờ\\nNhớ nhớ em trong mơ\",\"local_images\":[\"images/poem_1216_img_0.webp\"]},{\"id\":1213,\"title\":\"Tuyết nguyệt phong sương giăng ngập lối\",\"date\":\"2023-12-15T15:02:32\",\"date_formatted\":\"15 tháng 12, 2023\",\"genre\":\"Thất ngôn tứ tuyệt\",\"content_text\":\"Tuyết nguyệt phong sương giăng ngập lối\\nSương mờ nhân ảnh khó phôi phai\\nẢo mộng hồng trần sầu muôn kiếp\\nDuyên nợ hồng trần dễ phai phôi\",\"local_images\":[\"images/poem_1213_img_0.webp\"]},{\"id\":1194,\"title\":\"Tương tư nét vẻ thơ ngây\",\"date\":\"2023-07-21T18:08:06\",\"date_formatted\":\"21 tháng 7, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Tương tư nét vẻ thơ ngây\\nÂn cần đặt nhẹ lên môi má nàng\\nMang thêm dáng vẻ ngang tàng\\nĐặt vào ánh mắt muôn vàn yêu thương!\\nAn yên chẳng chút muộn phiền\\nNhân sinh chẳng biết vô tình hữu duyên\\n\\n\\n\\n\\n\\nHồng trần đâu dễ phai phôi\\nOanh vàng cất tiếng rầm rì thế gian\\nÀ ơi một kiếp xuân thì\\nIn trong cõi mộng mơ gì thế gian\\nAn yên chẳng chút muộn phiền\\nNhân sinh chẳng biết vô tình hữu duyên\",\"local_images\":[\"images/poem_1194_img_0.webp\"]},{\"id\":1191,\"title\":\"Một ngôi nhà nhỏ giữa thảo nguyên\",\"date\":\"2023-07-21T18:02:41\",\"date_formatted\":\"21 tháng 7, 2023\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Một ngôi nhà nhỏ giữa thảo nguyên\\nKhông mong danh lợi, chẳng muộn phiền\\nĐất xanh gieo chút mầm cây nhỏ\\nAo cạn thả trôi mấy bọt bèo!\\n\\n\\n\\n\\n\\nNắng trải trên vai xuống góc nhà\\nMưa phùn đượm ướt lá với hoa\\nSương trà đương tỏa trong nắng mới\\nAn yên chờ đợi cạnh hiên nhà\",\"local_images\":[\"images/poem_1191_img_0.webp\"]},{\"id\":1188,\"title\":\"Ngàn năm chỉ đợi một người\",\"date\":\"2023-07-21T17:58:55\",\"date_formatted\":\"21 tháng 7, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Ngàn năm chỉ đợi một người\\nTrăm năm chuyển kiếp có quên bao giờ\\nHỏi rằng nàng có thờ ơ\\nHay duyên đã rớt cõi mơ mộng nào!\\n\\n\\n\\n\\n\\n\\nĐời ta như lá với hoa\\nLá theo gió cuốn, hoa tàn có hay\\nThế gian duyên số hợp tan\\nVội đi rồi để vội vàng bước qua\\n\\n\\n\\n\\n\\n\\nĐời người như cát với mây\\nCát theo gió lộng, mây bay không ngừng\\nPhù du duyên nợ tràn đầy\\nMê cung số phận nào đây vô hình\",\"local_images\":[\"images/poem_1188_img_0.webp\"]},{\"id\":1184,\"title\":\"Kiếp nhân sinh buồn vui thoáng chốc\",\"date\":\"2023-07-21T17:55:46\",\"date_formatted\":\"21 tháng 7, 2023\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Kiếp nhân sinh buồn vui thoáng chốc\\nĐời vô thường sầu muộn ưu tư\\nCó chăng? E phù du trần thế\\nBụi muộn phiền phủ khắp thế gian!\\nChân ta bước vội vàng trên cát\\nIn dấu hằn mất mát thời gian\\nTia nắng hồng soi khắp thế gian\\nRải muộn phiền sau hàng lá nhỏ\",\"local_images\":[\"images/poem_1184_img_0.webp\"]},{\"id\":1177,\"title\":\"Tôi lạc ở đây góc xế chiều\",\"date\":\"2023-04-20T13:32:07\",\"date_formatted\":\"20 tháng 4, 2023\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Tôi lạc ở đây góc xế chiều\\nHàng cây chen đá, lá liêu xiêu\\nGót hồng mơ mộng nhiều đêm trắng\\nĐìu hiu bến nhỏ, ráng bóng chiều!\\n\\n\\n\\n\\n\\nThiên thu muôn kiếp sầu vô hận\\nKhoảnh khắc tơ lòng chốc vụt tan\\nCảnh cũ đò xưa còn đón khách\\nTrăng xưa chẳng khuất mối tơ lòng\",\"local_images\":[\"images/poem_1177_img_0.webp\"]},{\"id\":1174,\"title\":\"Thưa cha con đi lấy chồng\",\"date\":\"2023-03-01T15:37:42\",\"date_formatted\":\"1 tháng 3, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Thưa cha con đi lấy chồng\\nỞ bên người ấy có bằng lòng không?\\nNgày thơ, xưa bé lông bông\\nTrên tay cha đã bế bồng sớm hôm!\\nKhúc khích khẽ khóc rồi cười\\nGian nan vất vả để ngoài hiên phơi\\nGiờ đây sương gió trắng trời\\nThấu trong tim có mở lời cùng ai\\nDịu dàng đôi mắt hiền nai\\nSầu lên khóe mắt biết ai tìm về!\",\"local_images\":[\"images/poem_1174_img_0.webp\"]},{\"id\":1171,\"title\":\"Đêm quá ngắn với những tâm sự buồn\",\"date\":\"2023-03-01T15:33:03\",\"date_formatted\":\"1 tháng 3, 2023\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Đêm quá ngắn với những tâm sự buồn\\nNgày quá dài với những suy tư\\nTháng năm trôi muộn phiền ở lại\\nChông chênh đời ngắm cõi hư vô!\\nKiếp nhân sinh là sầu hay khổ\\nCõi thế gian sao đượm ưu hoài\\nTa lạc lối giữa dòng vô tận\\nTrầm luân hồi ai oán suy tư...\",\"local_images\":[\"images/poem_1171_img_0.webp\"]},{\"id\":1168,\"title\":\"Có một thứ khiến đời ta cô quạnh\",\"date\":\"2023-02-23T14:23:17\",\"date_formatted\":\"23 tháng 2, 2023\",\"genre\":\"Tự do\",\"content_text\":\"Có một thứ khiến đời ta cô quạnh\\nNgắm trăng tàn và lạnh tay người thương\\nTrời còn sáng và tối, nhưng ta chỉ lạc lối\\nTìm đường về mà vô lối người thương\",\"local_images\":[\"images/poem_1168_img_0.webp\"]},{\"id\":1165,\"title\":\"Nhân sinh trong một kiếp người\",\"date\":\"2023-02-23T14:20:55\",\"date_formatted\":\"23 tháng 2, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Nhân sinh trong một kiếp người\\nGió đưa mây thoảng như lời hư không\\nPhong sương phủ kín bụi trần\\nNhân duyên như rót muôn phần cô đơn\",\"local_images\":[\"images/poem_1165_img_0.webp\"]},{\"id\":1162,\"title\":\"Trường giang sóng cuộn về xuôi\",\"date\":\"2023-02-23T14:18:24\",\"date_formatted\":\"23 tháng 2, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Trường giang sóng cuộn về xuôi\\nMắt ai ướt lệ ngậm ngùi vì ai\\nHai dòng lệ nhỏ tuôn rơi\\nSông sâu mất đáy nhớ thương ngậm ngùi\",\"local_images\":[\"images/poem_1162_img_0.webp\"]},{\"id\":1159,\"title\":\"Nhìn kìa em con chúng ta đó\",\"date\":\"2023-02-23T14:13:28\",\"date_formatted\":\"23 tháng 2, 2023\",\"genre\":\"Tự do\",\"content_text\":\"Nhìn kìa em con chúng ta đó\\nMắt bé nhỏ nhưng xoe tròn nũng nịu\\nTóc lưa thưa như chứa cả mùa xuân\\nĐường chân trời kề bên vầng trán nhỏ!\\nSóng mũi dài như dáng đứng quê hương\\nMỉm miệng cười giữ niềm thương ở lại\\nMá bềnh bồng giống em, hay dỗi hờn\",\"local_images\":[\"images/poem_1159_img_0.webp\"]},{\"id\":1156,\"title\":\"Trời đổ lửa cho mắt vàng hoe\",\"date\":\"2023-02-23T14:00:58\",\"date_formatted\":\"23 tháng 2, 2023\",\"genre\":\"Thất ngôn\",\"content_text\":\"Trời đổ lửa cho mắt vàng hoe\\nEm lặng thầm khẽ khóc vai anh\\nMàn sương trắng mỏng như tấm lụa\\nMuôn sợi tơ ngăn cách mối tơ lòng!\\nĐêm đã qua, trời đừng vội sáng\\nPhút gần gũi để xa cách ngàn ngày\\nGió heo may từng cơn lạnh lẽo\\nNắng dần tàn héo hắt lòng ta\\nCười một chút, đời là bể khổ\\nBuồn hai hàng lệ đổ ướt mi\\nBuông theo gió còn có lại gì\\nSỏi khô cằn, đá hóa tâm hồn!\",\"local_images\":[\"images/poem_1156_img_0.webp\"]},{\"id\":1154,\"title\":\"Trên cành quyên liễu có đôi\",\"date\":\"2023-02-23T13:49:59\",\"date_formatted\":\"23 tháng 2, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Trên cành quyên liễu có đôi\\nThế tôi có thể nên đôi với nàng\\nTrời chiều len chút nắng vàng\\nDịu dàng ai đặt cho nàng cạnh tôi!\\nÁnh trăng kia biết dối lừa\\nKhuyết chăng một nửa cho vừa dáng nàng\\nCon đò lỡ bước sang ngang\\nCho tôi một chút vội vàng ngẩn ngơ\\nNàng thơ ơi hỡi nàng thơ\\nTên chi có thể giả vờ buông lơi\\nCho tôi gửi chút đôi lời\\nCó duyên gặp lại ngỏ lời nên duyên\",\"local_images\":[\"images/poem_1154_img_0.webp\"]},{\"id\":1150,\"title\":\"Hẹn người ở tuổi đôi mươi\",\"date\":\"2023-02-23T13:48:51\",\"date_formatted\":\"23 tháng 2, 2023\",\"genre\":\"Lục bát\",\"content_text\":\"Hẹn người ở tuổi đôi mươi\\nTóc xanh đã trải, mắt môi má hồng\\nLỡ dòng khẽ bước sang ngang\\nNhạt màu nắng rớt hai hàng lệ rơi!\\nXuân xanh thời cũng có thời\\nHoa xuân đâu chỉ một đời hoa xuân\\nĐành lòng nhẹ bước bâng khuâng\\nTuổi xuân gửi lại bên nhành hoa xuân\",\"local_images\":[\"images/poem_1150_img_0.webp\"]},{\"id\":1140,\"title\":\"Tiễn con đi khi đầu hai thứ tóc\",\"date\":\"2022-12-12T17:54:39\",\"date_formatted\":\"12 tháng 12, 2022\",\"genre\":\"Tự do\",\"content_text\":\"Tiễn con đi khi đầu hai thứ tóc\\nĐón con về tóc mẹ bạc phai\\nSinh con ra với hình hài nhỏ bé\\nĐón con về khi đất đá lẫn xương khô!\\nChén cơm bạc, xới vội nửa lưng\\nCơm chưa tròn con lại đi cho kịp\\nTiếng Tổ quốc hòa nhịp con tim\\nNhững tiếng nấc muộn phiền gói lại\\nHành trang con đi phải mãi vững lòng\\nĐã qua rồi năm ròng tháng rã\\nChén cơm vội, con đã ăn đâu\\nLần gặp gỡ biết đâu là lần cuối\\nBóng lưng con khuất núi sau hè\\nKhi gặp lại đã không còn giặc nữa\\nCon trở về bên chái bếp sau hè\\nNghe mẹ ru như những ngày thơ bé\\nChỉ chạnh lòng không được ấp ôm mẹ\",\"local_images\":[\"images/poem_1140_img_0.webp\"]},{\"id\":1137,\"title\":\"Mẹ trăm tuổi bạc đầu sương muối\",\"date\":\"2022-12-12T17:52:32\",\"date_formatted\":\"12 tháng 12, 2022\",\"genre\":\"Tự do\",\"content_text\":\"Mẹ trăm tuổi bạc đầu sương muối\\nĐón con về bên núi non thơ\\nNgày thuở bé chỉ mơ và mộng\\nMái nhà tranh gió lộng tứ bề!\\nLúc thơ bé được bế bồng chiều chuộng\\nLưng mẹ gầy con ngủ suốt thâu đêm\\nLớn lên trên đất cằn khô sỏi\\nƯớc mơ nhỏ qua cơn đói từng ngày\\nGiặc lại đến đốt cháy giấc mơ nhỏ\\nKiếp nô lệ có còn thấy tự do\\nCon đã đi theo màu cờ đỏ\\nMáu nhuộm bùn, đỏ khắp Việt Nam\\nNước đã sang trang nhưng ngàn người ở lại\\nDưới đất sâu mãi với thời gian\\nĐủ gian khổ, hình hài về với mẹ\\nMắt đã mờ ghi mãi bóng hình con\\nMâm cơm nhạt bớt đi nhiều nước mắt\\nChút khói hương mẹ ấm một chút lòng\\nHình đất nước in bóng hình con đó\\nTựa lưng vào thân gầy gò mẹ hiền\\nBóng của cha đã từng chinh chiến\\nCho hôm nay đất nước mãi vững bền!\",\"local_images\":[\"images/poem_1137_img_0.webp\"]},{\"id\":1132,\"title\":\"Tôi nhớ Sa Pa mùa tuyết lạnh\",\"date\":\"2022-12-08T08:42:57\",\"date_formatted\":\"8 tháng 12, 2022\",\"genre\":\"Thất ngôn\",\"content_text\":\"Tôi nhớ Sa Pa mùa tuyết lạnh\\nSương mờ phủ trắng mặt người qua\\nLữ khách phương xa vờ chẳng thấy\\nSương lạnh bờ môi ướt lệ nhòa!\\nNgày ấy khi trời còn nắng đẹp\\nChồi xanh đương mọc với lá hoa\\nKiêu sa bước đến cạnh bên ta\\nMây mù bỗng chốc cũng nhạt nhòa\\nNắng vừa khẽ lên nắng vội tắt\\nVô tình? Hữu ý? Băng kết hoa\\nMỗi phút mỗi giây xa cách xa\\nMỗi phương mỗi hướng hóa hư không\\nBăng tâm, sương kín mây ngập lối\\nĐộc bộ, đơn hành, ta với ta\",\"local_images\":[\"images/poem_1132_img_0.webp\"]},{\"id\":1121,\"title\":\"Em ơi dáng hình đất nước\",\"date\":\"2022-05-12T16:53:37\",\"date_formatted\":\"12 tháng 5, 2022\",\"genre\":\"Lục bát\",\"content_text\":\"Em ơi dáng hình đất nước\\nCao như Thái Sơn, sâu tựa lòng mẹ\\nTừng con sóng cứ vỗ về\\nNhư lời mẹ hát ru những đêm hè!\\nGió chảy qua miền sơn cước\\nPhủ lên tóc cha những sợi bạc màu\\nHình đất nước thật hùng vĩ\\nNhư cách ông bà ta đã yêu nhau\\nNúi sông kia phai bạc màu\\nAo sâu và biển khô cạn đáy\\nNhững tâm hồn còn nhỏ bé\\nXây dựng hình hài của cả núi sông!\\nLớn lên con xa đất mẹ\\nÔm trọn hình hài đất nước bên mình\\nSông dù sâu cũng ra bể\\nSuối dẫu cạn cũng bắt đầu từ nguồn\\nCon dù sống ở bốn phương\\nQuê cha đất mẹ vấn vương không ngừng\\nMong sao nghe được tin mừng\\nQuê hương đất nước tưng bừng niềm vui!\",\"local_images\":[\"images/poem_1121_img_0.webp\"]},{\"id\":1101,\"title\":\"Em chỉ ước thế gian không quá rộng\",\"date\":\"2022-01-16T23:31:29\",\"date_formatted\":\"16 tháng 1, 2022\",\"genre\":\"Tự do\",\"content_text\":\"Em chỉ ước thế gian không quá rộng\\nĐể yếu lòng, quay lại sẽ gặp anh\\nDẫu mong manh như muôn lớp lụa\\nNhưng nhủ lòng như lúa đợi mưa rào!\\nNhưng tại sao khi ta càng mong đợi\\nCàng vô tình vác thêm nỗi ưu phiền\\nCó hay không nơi đó người vẫn thế\\nChút mong chờ hay đã hóa hư không\",\"local_images\":[\"images/poem_1101_img_0.webp\"]},{\"id\":1088,\"title\":\"Cỏ trắng sương xanh trải sườn đồi\",\"date\":\"2022-01-12T23:16:22\",\"date_formatted\":\"12 tháng 1, 2022\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Cỏ trắng sương xanh trải sườn đồi\\nHai người một lối chẳng chung đôi\\nKhói xa ám trên màu lá biếc\\nMây hờn trôi nhẹ biết về đâu!\\n\\n\\n\\n\\n\\nNhà anh xanh cây, cỏ chẳng thiếu\\nNắng chiều xuyên qua chồi lá nhỏ\\nBước chân vừa đó ngỡ xa nhiều\\nMây trôi nắng tắt cũng đìu hiu\",\"local_images\":[\"images/poem_1088_img_0.webp\"]},{\"id\":1086,\"title\":\"Đã có lúc đời ta như bất biến\",\"date\":\"2022-01-12T03:31:10\",\"date_formatted\":\"12 tháng 1, 2022\",\"genre\":\"Tự do\",\"content_text\":\"Đã có lúc đời ta như bất biến\\nPhương trình tìm hoài vẫn vô nghiệm\\nThêm em vào phương trình lại có nghiệm\\nNhưng âm dương hay vô cực đủ đường!\\nXích ma tình từ không đến vô cực\\nChỉ tiệm cận chứ chưa hề giao cắt\\nTrục hoành anh trao, trục tung anh đợi\\nTiến sát mãi nhưng chẳng bao giờ gặp\",\"local_images\":[\"images/poem_1086_img_0.webp\"]},{\"id\":1083,\"title\":\"Cành tre mà có lá đa\",\"date\":\"2022-01-12T03:12:24\",\"date_formatted\":\"12 tháng 1, 2022\",\"genre\":\"Lục bát\",\"content_text\":\"Cành tre mà có lá đa\\nNhư con chim sẻ trong nhà diều hâu\\nTương tư anh gửi thật sâu\\nGiấu trong giếng cạn dám đâu nói gì!\\nBiển cạn thì có khi đầy\\nLòng không khô cạn, chẳng vơi nỗi sầu\\nHỏi rằng em có biết đâu\\nLòng anh rẽ sóng nhưng trôi ngược dòng\",\"local_images\":[\"images/poem_1083_img_0.webp\"]},{\"id\":1055,\"title\":\"Sóng tràn mắt biếc, hoa khô lệ\",\"date\":\"2021-12-30T20:38:49\",\"date_formatted\":\"30 tháng 12, 2021\",\"genre\":\"Thất ngôn tứ tuyệt\",\"content_text\":\"Sóng tràn mắt biếc, hoa khô lệ\\nNắng dài trên cát, biển cằn khô\\nLiễu rũ đào phai vàng theo lá\\nCỏ xanh ủ rạp dưới tàn hoa\",\"local_images\":[\"images/poem_1055_img_0.webp\"]},{\"id\":1049,\"title\":\"Màu xanh ba vẽ biển\",\"date\":\"2021-12-07T09:01:46\",\"date_formatted\":\"7 tháng 12, 2021\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Màu xanh ba vẽ biển\\nMàu trắng thì vẽ mây\\nTrong đôi mắt thơ ngây\\nCon vẽ nụ cười hồng!\\n\\n\\n\\n\\n\\nSắc bông vừa chớm nở\\nGió trên tóc bồng bềnh\\nHương thơm bên cỏ lá\\nHôn lên má dịu dàng\\n\\n\\n\\n\\n\\nĐôi mắt khẽ mơ màng\\nBàn tay thon bé xíu\\nÔm cả trời thương nhớ\\nBên nụ hồng vấn vương.\",\"local_images\":[\"images/poem_1049_img_0.webp\"]},{\"id\":1027,\"title\":\"Con cho ba nụ cười, ngây thơ và mộng mơ\",\"date\":\"2021-08-14T21:24:28\",\"date_formatted\":\"14 tháng 8, 2021\",\"genre\":\"Tự do\",\"content_text\":\"Con cho ba nụ cười, ngây thơ và mộng mơ\\nCon cho ba mong nhớ, cả một trời yêu thương\\nVấn vương trên khóe mắt hay môi chúm chím cười\\nQuên đời đầy vất vả, khó nhọc và gian lao!\\nTrời còn cao và xanh, như đôi mắt long lanh\\nCon gieo từng bước nhỏ vào trong hồn ba ba\\nĐời có qua nhiều kiếp, trong muôn vạn cuộc đời\\nCon vẫn mãi bé nhỏ là con gái của ba\",\"local_images\":[\"images/poem_1027_img_0.webp\"]},{\"id\":887,\"title\":\"Con ngồi con vẽ vầng mây\",\"date\":\"2021-02-04T09:50:12\",\"date_formatted\":\"4 tháng 2, 2021\",\"genre\":\"Lục bát\",\"content_text\":\"Con ngồi con vẽ vầng mây\\nBa ngồi ba ngắm cả ngày yêu thương\\nTô thêm một chút màu hường\\nVẽ nên cả núi yêu thương gia đình!\\n\\n\\n\\n\\n\\nLong lanh đôi mắt nụ cười\\nTóc mây ngang mái đánh rơi hững hờ\\nNét trông có chút ngây thơ\\nNét trông già dặn hững hờ sự đời\",\"local_images\":[\"images/poem_887_img_0.webp\"]},{\"id\":885,\"title\":\"Mong manh giấy trắng vẽ nụ cười\",\"date\":\"2021-02-04T09:49:53\",\"date_formatted\":\"4 tháng 2, 2021\",\"genre\":\"Lục bát\",\"content_text\":\"Mong manh giấy trắng vẽ nụ cười\\nSắc Xuân tô điểm thêm lời yêu thương\\nMá hồng chưa phủ phong sương\\nNụ cười chưa chút vấn vương u sầu!\\n\\n\\n\\n\\n\\nNgười đâu gặp gỡ lần đầu\\nTương tư gieo hết lên đầu yêu thương\\nThế gian thêm chút cõi hường\\nYêu thương rồi lại muôn phần yêu thương!\",\"local_images\":[\"images/poem_885_img_0.webp\"]},{\"id\":880,\"title\":\"Mong manh như trang giấy\",\"date\":\"2021-02-04T09:49:28\",\"date_formatted\":\"4 tháng 2, 2021\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Mong manh như trang giấy\\nĐôi mắt thơ dịu hiền\\nCon cho ba hỏi nhỏ\\nCon có phải cô tiên!\\nXua đi hết muộn phiền\\nGieo mong manh nỗi nhớ\\nNhư nàng thơ xứ Huế\\nChợt vô tình gọi tên!\",\"local_images\":[\"images/poem_880_img_0.webp\"]},{\"id\":809,\"title\":\"Có những lúc ta thả dòng suy nghĩ\",\"date\":\"2021-02-03T16:37:01\",\"date_formatted\":\"3 tháng 2, 2021\",\"genre\":\"Tự do\",\"content_text\":\"Có những lúc ta thả dòng suy nghĩ\\nNgọn cỏ ven đường sao với được mây\\nNhưng mây kia có chạm được tới cỏ\\nHay vội tan khi nắng mới vừa lên.\\nCũng như chút lãng quên dòng ký ức\\nTa muốn chạm, nhưng dường như xa quá\\nMỏi mong chờ những thứ đã đi qua...\",\"local_images\":[\"images/poem_809_img_0.webp\"]},{\"id\":783,\"title\":\"Nếu sóng không từ gió\",\"date\":\"2021-01-22T15:33:27\",\"date_formatted\":\"22 tháng 1, 2021\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Nếu sóng không từ gió\\nBiển có chút êm đềm?\\nNếu nắng không còn ấm\\nĐêm về có dịu êm?\\nSau lưng những tầng lá\\nNgười như hoa như cỏ\\nNhưng lòng ta bé nhỏ\\nNgước mắt nhìn trời xa\",\"local_images\":[\"images/poem_783_img_0.webp\"]},{\"id\":780,\"title\":\"Ngoài kia vất vả gian lao\",\"date\":\"2021-01-22T15:23:16\",\"date_formatted\":\"22 tháng 1, 2021\",\"genre\":\"Lục bát\",\"content_text\":\"Ngoài kia vất vả gian lao\\nMẹ già tần tảo sớm hôm một mình\\nChờ mong mòn mỏi một tin\\nXuân về Tết đến có con trở về!\\n\\n\\n\\n\\n\\nVề bên chái bếp hiên nhà\\nĐể quên vất vả bên ngoài thế gian\\nDẫu về phút chốc vội vàng\\nMột lần gặp gỡ hơn ngàn nhớ thương.\",\"local_images\":[\"images/poem_780_img_0.webp\"]},{\"id\":773,\"title\":\"Phong sương gieo gió trong cõi mộng\",\"date\":\"2021-01-04T17:43:54\",\"date_formatted\":\"4 tháng 1, 2021\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Phong sương gieo gió trong cõi mộng\\nHồng trần lạc lối với tình ai\\nTrăng nghiêng qua ánh trên mái tóc\\nLiễu phủ đào tơ với mộng huyền!\\n\\n\\n\\n\\n\\nÓng ánh sóng gieo thuyền âm sắc\\nGiọng hát phôi pha át nỗi lòng\\nLữ khách vô tình qua phương ấy\\nĐọng chút trong tâm có muộn phiền!\",\"local_images\":[\"images/poem_773_img_0.webp\"]},{\"id\":765,\"title\":\"Trúc Giang hành trình 15 năm\",\"date\":\"2020-09-14T14:04:18\",\"date_formatted\":\"14 tháng 9, 2020\",\"genre\":\"Lục bát\",\"content_text\":\"Mười lăm năm cuộc hành trình,\\nTrúc Giang vượt khó vươn mình đi lên!\\nNhớ ngày thành lập đầu tiên,\\nGian nan vất vả, khó khăn vô vàn!\\nTưởng chừng không thể vượt qua,\\nChặng đường phía trước nào ta có ngờ!\\nNhân sự, tiền vốn, độ trình,\\nThị trường kinh nghiệm có bằng ai đâu!\\nVậy mà dám nghĩ dám làm,\\nMùng năm tháng chín Trúc Giang ra đời!\\nMười lăm năm cuộc hành trình,\\nTrúc Giang bước tiếp chặng đường đi lên!\\nẤm no hạnh phúc đủ đầy,\\nNhân viên, cán bộ sum vầy anh em!\\nChúng ta xây dựng Trúc Giang,\\nSánh vai cùng với anh em bạn bè!\\nNăm năm nữa có là bao!\\nHẹn nhau gặp mặt Thủ Đô bao đời!\\nKính dâng lên Bác một lời,\\n\\\"Chúng con đã trọn lời thề\\nTrúc Giang xây dựng ước mơ ban đầu!\\\"\",\"local_images\":[\"images/poem_765_img_0.webp\"]},{\"id\":726,\"title\":\"Đất nước mình đẹp lắm phải không anh\",\"date\":\"2020-01-16T10:53:06\",\"date_formatted\":\"16 tháng 1, 2020\",\"genre\":\"Tự do\",\"content_text\":\"Đất nước mình đẹp lắm phải không anh\\nBao mái nhà tranh chỉ còn dĩ vãng\\nNhững cánh đồng bát ngát hóa nhà máy\\nNhững máy cày thay trâu trên đồng lúa.\\n\\n\\n\\n\\n\\nChiếc xe đạp mẹ chở em ngày nào\\nChỉ còn mãi trong ký ức xa xăm\\nĐôi vai cha vác cày thay trâu\\nÁo bạc màu giờ chẳng đâu tìm thấy\\n\\n\\n\\n\\n\\nĐời nô lệ mỏng manh như tờ giấy\\nBỗng chốc tự do xóa gông cùm\\nRuộng đất bao la trở lại tay ta\\nTừng tấc đất đều hóa những tấc vàng\\n\\n\\n\\n\\n\\nRuộng lúa thênh thang trên từng đồi nhỏ\\nSóng vỗ về đưa cá mực đầy khoang\\nÁnh mặt trời vàng trên từng bãi cát\\nNhững hàng người ca hát trong tự do\\n\\n\\n\\n\\n\\nĐiện đến buôn làng, nước thênh thang\\nKhoảng cách xa như gần sát lại\\nKhỏa lấp dần ở hai đầu nỗi nhớ\\nKết nối mọi miền hòa với yêu thương\\n\\n\\n\\n\\n\\nCho ta gửi những vấn vương về thời gian khó\\nĐất nước thần kỳ vượt trên từng con sóng nhỏ\\nLuôn vươn mình đối mặt với gió to\\nTìm đích đến của tự do và hạnh phúc\",\"local_images\":[\"images/poem_726_img_0.webp\"]},{\"id\":700,\"title\":\"Em ơi em sớm mai vừa thức giấc\",\"date\":\"2019-10-15T17:58:53\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Tự do\",\"content_text\":\"Em ơi em sớm mai vừa thức giấc\\n\\nCó phải mình vẫn trong giấc chiêm bao\\n\\nVẫn nụ hôn còn mãi chút ngọt ngào\\n\\nNhư nắng ấm len vào trong cõi mộng\",\"local_images\":[\"images/poem_700_img_0.webp\"]},{\"id\":697,\"title\":\"Cà phê đắng ru tình còn mặn\",\"date\":\"2019-10-15T17:54:53\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Thất ngôn tứ tuyệt\",\"content_text\":\"Cà phê đắng ru tình còn mặn\\n\\nSầu hững hờ xa vắng mắt ai\\n\\nGiọt sương mai vương buồn khóe mắt\\n\\nVướng chút tình vị đắng lên môi\",\"local_images\":[\"images/poem_697_img_0.webp\"]},{\"id\":694,\"title\":\"Đất Phật bình yên trời một cõi\",\"date\":\"2019-10-15T17:53:49\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Thất ngôn tứ tuyệt\",\"content_text\":\"Đất Phật bình yên trời một cõi\\n\\nNon sông gấm vóc vững muôn đời\\n\\nBình yên bác ái dang tay rộng\\n\\nÔm trọn non sông mãi một nhà!\",\"local_images\":[\"images/poem_694_img_0.webp\"]},{\"id\":691,\"title\":\"Bước một bước, ta giữa đời cô độc\",\"date\":\"2019-10-15T17:52:35\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Tự do\",\"content_text\":\"Bước một bước, ta giữa đời cô độc,\\n\\nChút nỗi lòng rồi biết trải cùng ai!\\n\\nĐường dẫu dài nhưng chẳng ngại gian khổ,\\n\\nLữ khách đường xa chỉ sợ một mình!\\n\\n\\nHoa tàn hoa héo ai cũng biết,\\n\\nTa buồn ta tủi mấy ai hay!\\n\\nĐứng giữa dòng vô thường, đời tấp nập,\\n\\nChỉ mình ta mình ta với mình ta!\",\"local_images\":[\"images/poem_691_img_0.webp\"]},{\"id\":688,\"title\":\"Vệt nắng cuối chiều còn hiu hắt\",\"date\":\"2019-10-15T17:51:11\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Vệt nắng cuối chiều còn hiu hắt\\n\\nCon đường xưa đã vắng tên em\\n\\nBuổi chiều êm như làn gió nhỏ\\n\\nKhẽ thẫn thờ nhỏ nhắc tên em!\\n\\nChim đã về ngàn tìm chốn ngủ\\n\\nAnh về chốn cũ không còn em\\n\\nTrời đã chen vào trong đôi mắt\\n\\nChút sầu chút hận vẫn chút thương\",\"local_images\":[\"images/poem_688_img_0.webp\"]},{\"id\":685,\"title\":\"Anh đâu phải là đá\",\"date\":\"2019-10-15T17:48:09\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Anh đâu phải là đá\\n\\nCũng chẳng phải cỏ cây\\n\\nChỉ như mơ ban ngày\\n\\nMà chưa kịp tỉnh giấc!\\n\\nTrong giấc mộng có em\\n\\nChỉ còn là dĩ vãng\\n\\nMàu nắng vàng cuối phố\\n\\nNhạt theo màu hoàng hôn\\n\\nRộn ràng theo con phố\\n\\nBước chân dần nhạt hơn\",\"local_images\":[\"images/poem_685_img_0.webp\"]},{\"id\":682,\"title\":\"Tôi không sợ nắng làm phai cuộc tình\",\"date\":\"2019-10-15T17:41:19\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Tự do\",\"content_text\":\"Tôi không sợ nắng làm phai cuộc tình\\n\\nTôi không sợ gió cuốn hết yêu thương\\n\\nTôi chỉ sợ không thể chung đường\\n\\nCủa hai kẻ đơn phương hoài chẳng gặp\",\"local_images\":[\"images/poem_682_img_0.webp\"]},{\"id\":679,\"title\":\"Mình thương nhau chút có được không\",\"date\":\"2019-10-15T17:37:03\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Thất ngôn\",\"content_text\":\"Mình thương nhau chút có được không!\\n\\nCho nắng xen thêm chút má hồng\\n\\nCho gió len qua từng kẽ lá\\n\\nCho nắng hôn lên má môi hồng!\\n\\n\\nMình thương nhau chút có được không!\\n\\nCho đường xa vắng hóa hư không\\n\\nCho nẻo đường xa gần sát lại\\n\\nCho hai đứa mãi gần không xa\\n\\n\\nEm ơi cho anh hỏi lần nữa\\n\\nMình thương nhau chút có được không!\",\"local_images\":[\"images/poem_679_img_0.webp\"]},{\"id\":676,\"title\":\"Đất hỡi đất, nước hỡi nước\",\"date\":\"2019-10-15T17:33:56\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Tự do\",\"content_text\":\"Đất hỡi đất, nước hỡi nước\\n\\nCó nỗi buồn nào cho ta là vô tận\\n\\nCó hạt mưa nào rơi bên cửa\\n\\nCho gió lạnh về, nắng chợt tan!\\n\\n\\nCho những cánh tay buông vội rời\\n\\nCho cả những con đường xưa lối nhỏ\\n\\nBước ta về chỉ còn ta vội vã\\n\\nNắng tựa lưng thềm, áo nhạt phai\\n\\n\\nAi đã sai hoàng hôn dài kéo đến\\n\\nMây gió về kéo giông tố vội sang\\n\\nRồi chợt ướt vai kẻ lang thang\\n\\nKẻ vội vàng, bỏ hoang dòng suy nghĩ\",\"local_images\":[\"images/poem_676_img_0.webp\"]},{\"id\":673,\"title\":\"Anh bỏ lỡ tình em\",\"date\":\"2019-10-15T17:26:50\",\"date_formatted\":\"15 tháng 10, 2019\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Anh bỏ lỡ tình em\\n\\nGiữa một trời hoa trắng\\n\\nNhư mây kia và nắng\\n\\nChẳng tiến bước cùng nhau!\\n\\n\\nCánh cò trắng ngày nào\\n\\nBay qua đồng êm ả\\n\\nSao em không buông thả\\n\\nChút thương nhớ về anh\\n\\n\\nTrời còn xanh và nắng\\n\\nBiển còn sóng và gió\\n\\nSao em không còn đó\\n\\nNhớ thương và yêu anh\\n\\n\\nGió đi đến phương trời\\n\\nNgười ngang qua lối cũ\\n\\nNắng và gió cùng nhau\\n\\nLại ngược lối yêu thương\",\"local_images\":[\"images/poem_673_img_0.webp\"]},{\"id\":513,\"title\":\"Nắng bỏ ta đi, nắng không về nữa\",\"date\":\"2018-04-17T05:45:11\",\"date_formatted\":\"17 tháng 4, 2018\",\"genre\":\"Tự do\",\"content_text\":\"Nắng bỏ ta đi, nắng không về nữa\\n\\nDốc cạn lòng chỉ thấy những cơn mưa\\n\\nĐường trăm nẻo, đường về chỉ một\\n\\nMưa trăm hướng sao chỉ ướt mình ta!\\n\\n\\nChút hoa, chút trăng, chút gió, chút tình\\n\\nCho ta khẽ chút bình minh một mình\\n\\nThênh thang vạn nẻo muôn đường xa khuất\\n\\nKhói mờ sương ảnh lấp muôn bóng hình\",\"local_images\":[\"images/poem_513_img_0.webp\"]},{\"id\":505,\"title\":\"Người trao có nửa nụ cười\",\"date\":\"2018-04-05T19:42:16\",\"date_formatted\":\"5 tháng 4, 2018\",\"genre\":\"Lục bát\",\"content_text\":\"Người trao có nửa nụ cười\\n\\nMà ta mất cả một đời để quên\\n\\nQuên cho những tháng những ngày\\n\\nNhững giây những phút của thời gian trôi!\\n\\n\\nNụ cười một nửa vội vàng\\n\\nMang đi thân xác hai hàng ngẩn ngơ\\n\\nNgười vui khẽ nụ cười hờ\\n\\nCho ta vương vấn ngẩn ngơ suốt ngày\\n\\n\\nTa say chút gió chút tình\\n\\nVương trên ánh mắt vô tình khẽ qua\\n\\nNgười trao chút gió chút hoa\\n\\nHồn ta lại ngập đường hoa chốn về\\n\\n\\nCho ta một chút mải mê\\n\\nTương tư theo bước nàng về sớm hôm\\n\\nCho ta hôn khẽ tóc nàng\\n\\nCho mây với gió vội vàng mang theo\",\"local_images\":[\"images/poem_505_img_0.gif\"]},{\"id\":484,\"title\":\"Sài Gòn mưa gió trở trời\",\"date\":\"2017-05-03T15:23:01\",\"date_formatted\":\"3 tháng 5, 2017\",\"genre\":\"Lục bát\",\"content_text\":\"Sài Gòn mưa gió trở trời\\n\\nAnh ngồi anh ngắm một trời bình yên\\n\\nBao nhiêu sầu não muộn phiền\\n\\nAnh đem bỏ lại sau miền yêu thương!\\n\\n\\nNgày nào rồi cũng bình thường\\n\\nPhố phường rồi cũng ngập tràn yêu thương\\n\\nNơi nào anh cũng thấy em\\n\\nNơi nào cũng chỉ yêu thương một người\",\"local_images\":[\"images/poem_484_img_0.webp\"]},{\"id\":419,\"title\":\"Bài thơ tháng 10\",\"date\":\"2016-10-07T16:43:13\",\"date_formatted\":\"7 tháng 10, 2016\",\"genre\":\"Lục bát\",\"content_text\":\"Tháng năm vội vã trôi qua\\n\\nTháng Mười lại đến, thế là đông sang\\n\\nVui trong đông đến rộn ràng\\n\\nVẻ trông ấm áp, dịu dàng nắng mai.\\n\\nMọi việc rồi sẽ bình an\\n\\nChuyện chi cũng sẽ dễ dàng vượt qua\\n\\nThong dong giang cánh đại bàng\\n\\nSẻ chia hạnh phúc muôn vàn yêu thương\",\"local_images\":[\"images/poem_419_img_0.webp\"]},{\"id\":415,\"title\":\"Ngủ đi em, ngoài kia trời rất lạnh\",\"date\":\"2016-10-05T16:30:14\",\"date_formatted\":\"5 tháng 10, 2016\",\"genre\":\"Tự do\",\"content_text\":\"Ngủ đi em, ngoài kia trời rất lạnh\\n\\nMười ngón tay không ôm nổi muộn phiền\\n\\nĐêm hoài niệm với những điều đã cũ\\n\\nEm đừng buồn, em đáng được bình yên.\\n\\n\\nGió lại về trên khắp nẻo mọi miền\\n\\nTấm lưng trần phơi giữa đời giá lạnh\\n\\nBuốt căm hờn qua muôn vạn phong sương\\n\\nChỉ còn em nơi phố phường hoang vắng.\",\"local_images\":[\"images/poem_415_img_0.webp\"]},{\"id\":406,\"title\":\"Có những nỗi lòng chẳng bao giờ nói ra được\",\"date\":\"2016-10-05T16:22:07\",\"date_formatted\":\"5 tháng 10, 2016\",\"genre\":\"Tự do\",\"content_text\":\"Có những nỗi lòng chẳng bao giờ nói ra được\\n\\nSợ là giấc mơ theo cơn gió bay đi\\n\\nLửa âm ỉ chẳng bao giờ thành ngọn\\n\\nCháy tim ta từng chút dỗi hờn!\\n\\nCó lẽ cô đơn với đời ta là tri kỷ\\n\\nNỗi lòng ta như vạn tỷ mũi tên\\n\\nXuyên qua hết nhưng chẳng bao giờ chạm tới\\n\\nĐáy lòng ta vội vã giận hờn!\",\"local_images\":[\"images/poem_406_img_0.webp\"]},{\"id\":403,\"title\":\"Như chuông vang mãi tiếng lòng\",\"date\":\"2016-10-05T16:16:40\",\"date_formatted\":\"5 tháng 10, 2016\",\"genre\":\"Lục bát\",\"content_text\":\"Như chuông vang mãi tiếng lòng\\n\\nNgân lên trong khúc dịu dàng sắc xuân\\n\\nHạnh kia chung sức đi tìm\\n\\nPhúc đây vang đến mọi miền yêu thương\",\"local_images\":[\"images/poem_403_img_0.webp\"]},{\"id\":396,\"title\":\"Đông gõ cửa bên ngoài hiên vắng\",\"date\":\"2016-09-08T15:58:04\",\"date_formatted\":\"8 tháng 9, 2016\",\"genre\":\"Song thất lục bát\",\"content_text\":\"Đông gõ cửa bên ngoài hiên vắng\\n\\nĐưa thu và giọt nắng trôi xa\\n\\nMây giăng sương trắng nhạt nhòa\\n\\nGió đem hơi lạnh ghé qua ngoài thềm!\\n\\n\\nNhớ giây phút bên rèm ngóng đợi\\n\\nGiữa đêm khuya vời vợi nhớ thương\\n\\nGiọt châu tô ướt má hường\\n\\nGiờ người xa cách ở phương trời nào\\n\\n\\nTrăng hiu hắt ngó vào song cửa\\n\\nNét mi gầy, một nửa xanh xao\\n\\nBờ mi níu giấc chiêm bao\\n\\nVòng tay ân ái theo vào giấc mơ\\n\\n\\nChợt tỉnh giấc, không giờ rồi đó\\n\\nTái tê lòng cơn gió tràn qua\\n\\nĐể ai nước mắt nhạt nhòa\\n\\nCô đơn gối chiếc... tình qua lâu rồi.\",\"local_images\":[\"images/poem_396_img_0.webp\"]},{\"id\":389,\"title\":\"Đừng tưởng em không còn đây nữa\",\"date\":\"2016-07-30T08:27:32\",\"date_formatted\":\"30 tháng 7, 2016\",\"genre\":\"Tự do\",\"content_text\":\"Đừng tưởng em không còn đây nữa\\n\\nThì anh buồn anh khóc với cô đơn\\n\\nAnh vẫn vậy, vẫn tươi cười hóm hỉnh\\n\\nVẫn vô tư như khi có còn em!\\n\\n\\nBởi em xa nhưng ta là tri kỷ\\n\\nKhông thấy nhau nhưng vẫn tỏ yêu thương\\n\\nEm là gió, là khói sương tan biến\\n\\nAnh vô tình như nước biển chờ mong\\n\\n\\nSương kia rớt xuống dòng sông\\n\\nTrôi ra biển lớn anh mong mỏi chờ\\n\\nBơ vơ một chút hững hờ\\n\\nMong chờ một chút mong chờ thế thôi\",\"local_images\":[\"images/poem_389_img_0.webp\"]},{\"id\":385,\"title\":\"Anh là anh của hôm qua\",\"date\":\"2016-07-26T16:02:12\",\"date_formatted\":\"26 tháng 7, 2016\",\"genre\":\"Lục bát\",\"content_text\":\"Anh là anh của hôm qua\\n\\nEm là em của xót xa mất rồi\\n\\nNhìn trời sao lắm mây trôi\\n\\nGặp trong phút chốc để rồi cách xa!\\n\\n\\nChẳng qua cũng mối duyên đầu\\n\\nChẳng qua hai đứa quay đầu là xong\\n\\nVấn vương chi mãi tơ lòng\\n\\nĐường chia hai ngả đừng mong đợi gì\",\"local_images\":[\"images/poem_385_img_0.webp\"]},{\"id\":382,\"title\":\"Ta đi qua giữa dòng đời quá vội\",\"date\":\"2016-07-26T16:01:25\",\"date_formatted\":\"26 tháng 7, 2016\",\"genre\":\"Tự do\",\"content_text\":\"Ta đi qua giữa dòng đời quá vội\\n\\nChân lý tìm trôi nổi chốn nhân gian\\n\\nVới một cái dang tay ôm sầu hận\\n\\nPhận duyên tình có lẫn với sầu bi!\\n\\nTa quay bước tìm trong nỗi nhớ\\n\\nChỉ còn hình mờ chốn nhân gian\\n\\nĐã qua rồi thời gian có lại\\n\\nKhoảng xóa nhớ, cách chia xa\\n\\nCó là ta hay người xa lạ\\n\\nTìm chẳng thấy, hóa kẻ người dưng\\n\\nRồi ta dừng, bên đời vô thức\\n\\nĐể người tìm thực chất yêu thương\",\"local_images\":[\"images/poem_382_img_0.webp\"]},{\"id\":375,\"title\":\"Lời cuối tháng 12\",\"date\":\"2015-12-09T23:18:52\",\"date_formatted\":\"9 tháng 12, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Em cứ sống với cuộc sống của em đi\\n\\nĐể mình anh với mãi bước tình si\\n\\nBước đêm tối với một mình thầm lặng\\n\\nBiết nơi đâu có hiểu thấu được chăng?\\n\\nCó những lúc mây giăng về kín lối\\n\\nMưa bão bùng gió lạnh lại từng cơn\\n\\nĐể một mình cô đơn rồi giá lạnh\\n\\nKẻ vô tình cũng là kẻ cô đơn\\n\\nCó gì đúng, có gì sai hay ngang trái\\n\\nHay chúng mình chẳng phải của nhau\\n\\nKẻ bước nhanh trên con đường vội vã\\n\\nNgười vô tình bước thong thả dỗi hờn\\n\\nChẳng ai hơn cũng chẳng ai là kém\\n\\nMệt mỏi rồi cũng thèm chút sẻ chia\\n\\nNếu cứ thế đời chia lìa hai ngả\\n\\nVô tình không hay giá trả cô đơn\",\"local_images\":[\"images/poem_375_img_0.webp\"]},{\"id\":367,\"title\":\"Buồn vui cùng với nụ cười\",\"date\":\"2015-07-13T22:33:04\",\"date_formatted\":\"13 tháng 7, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Buồn vui cùng với nụ cười\\n\\nTrên môi chút đắng của thời gian trôi\\n\\nVẩn vơ như đã ngủ vùi\\n\\nTôi xuôi theo nắng buồn vui đôi đường!\\n\\nPhố phường cũng chút lặng im\\n\\nLim dim một giấc ngủ chìm thế gian\\n\\nSương kia có lúc phai tàn\\n\\nNgười sao có lúc vội vàng bước đi\\n\\nTình xưa còn ý nghĩa gì\\n\\nBuông tay là hết, thôi thì chia xa\\n\\nĐầu môi còn chút mặn mà\\n\\nĐã qua dòng nước mắt xa đôi bờ\\n\\nThẫn thờ cùng với nghĩ suy\\n\\nYêu sao một chút, hận chi muôn đời\",\"local_images\":[\"images/poem_367_img_0.webp\"]},{\"id\":363,\"title\":\"Tình như sương\",\"date\":\"2015-06-26T23:35:39\",\"date_formatted\":\"26 tháng 6, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Tình như sương\\n\\nChơi vơi\\n\\nĐời như khói\\n\\nRơi rơi!\\n\\nNgười cứ thế\\n\\nXa xa\\n\\nTa cứ thế\\n\\nBuồn bã!\\n\\n\\nRồi\\n\\n\\nTình vẫn vậy\\n\\nXa xôi\\n\\nĐời vẫn thế\\n\\nTrôi trôi!\\n\\nNgười vẫn vậy\\n\\nRời xa\\n\\nTa cứ thế\\n\\nMình ta\",\"local_images\":[\"images/poem_363_img_0.webp\"]},{\"id\":346,\"title\":\"Phố không tên đêm về vắng lặng\",\"date\":\"2015-03-29T23:07:40\",\"date_formatted\":\"29 tháng 3, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Phố không tên đêm về vắng lặng\\n\\nTình không tên tình đắng trong tim\\n\\nChôn vào sâu trong một nỗi niềm\\n\\nThở than đời dám trách vì ai!\\n\\n\\nChẳng ai sai cũng chẳng ai là đúng\\n\\nLà duyên tình thao túng cả thế gian\\n\\nBước vội vàng khi tình yêu vừa tới\\n\\nRồi xa dần khi tình mới vừa sang\\n\\n\\nCả thế gian nhân tình là như thế\\n\\nMãi hẹn thề như chẳng thể xa nhau\\n\\nRồi vội mau quên đi theo làn gió\\n\\nTỉnh mộng rồi, có còn đó yêu đương!\",\"local_images\":[\"images/poem_346_img_0.webp\"]},{\"id\":342,\"title\":\"Ngày xưa mưa gió dặm trường\",\"date\":\"2015-03-07T22:30:54\",\"date_formatted\":\"7 tháng 3, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Ngày xưa mưa gió dặm trường\\n\\nMẹ thường hay bảo con nương vào người\\n\\nNgoài trời mưa gió trắng tươi\\n\\nTrong vòng tay mẹ con cười con vui!\\n\\n\\nLớn lên sống giữa mọi người\\n\\nMưa trời vẫn đổ, nơi đâu tựa vào\\n\\nÀo ào như thác tuôn rơi\\n\\nNơi này con lạnh, chơi vơi một mình\\n\\n\\nXa xa trong gió lặng thinh\\n\\nCó nghe tiếng mẹ tâm tình mỗi đêm\\n\\nLời ru xa vẫn êm đềm\\n\\nThắm trong con lúc mỗi đêm ùa về\\n\\n\\nGiữa đời còn lắm u mê\\n\\nTìm đâu để thấy lối về mỗi đêm\\n\\nDù xa cách những đêm trường\\n\\nTình mẹ vẫn sáng soi đường con đi\",\"local_images\":[\"images/poem_342_img_0.webp\"]},{\"id\":337,\"title\":\"Tết đến rồi, xuân có vui gì không\",\"date\":\"2015-02-18T14:14:22\",\"date_formatted\":\"18 tháng 2, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Tết đến rồi, xuân có vui gì không\\n\\nHay niềm vui chỉ là để dối lòng\\n\\nMắt thì cười nhưng lòng nhói lệ\\n\\nMải mê tìm một thế giới ảo mộng!\\n\\n\\nỞ đó lòng tin là tất cả\\n\\nRồi phai tàn theo lá mùa thu\\n\\nĐời cứ mãi như là phù du\\n\\nTrôi theo sóng biết đâu mà tìm\\n\\n\\nThế giới đó tìm nhau có dễ\\n\\nCó nhau rồi, dễ mất hay không\\n\\nĐời là sống hay là tồn tại\\n\\nMãi tìm thứ không thuộc về mình\",\"local_images\":[\"images/poem_337_img_0.webp\"]},{\"id\":333,\"title\":\"Chẳng còn đâu những giờ phút đôi ta\",\"date\":\"2015-02-16T00:16:13\",\"date_formatted\":\"16 tháng 2, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Chẳng còn đâu những giờ phút đôi ta\\n\\nBước cùng nhau mặc cả thế giới sầu\\n\\nGiờ trong đêm chỉ còn ta mò mẫm\\n\\nBước đi cùng mà khác tận trong tâm!\\n\\n\\nGánh lỗi lầm chỉ một mình ta chịu\\n\\nChỉ mong người đời xiêu chút nỗi lòng\\n\\nNghiêng một chút cho đời bớt hối hả\\n\\nChút bình yên sao khó quá cuộc đời\",\"local_images\":[\"images/poem_333_img_0.webp\"]},{\"id\":331,\"title\":\"Tôi vẫn thế, vẫn một kẻ cô đơn\",\"date\":\"2015-02-16T00:15:30\",\"date_formatted\":\"16 tháng 2, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Tôi vẫn thế, vẫn một kẻ cô đơn\\n\\nBiết dỗi hờn khi đời nhiều ngang trái\\n\\nTôi có sai khi dòng đời hai lối\\n\\nBước ngược đường thành một lối người dưng!\\n\\n\\nĐời cũng từng là cả một bể vui\\n\\nNụ cười xinh chẳng thể tắt cuối đường\\n\\nNhưng đời là thứ bể khổ vô thường\\n\\nHết con đường rồi lại là vực thẳm\\n\\n\\nĐã níu kéo, nắm lấy trong vô vọng\\n\\nChút niềm tin sao nó quá mong manh\\n\\nRồi mọi thứ chỉ còn là mong đợi\\n\\nTrong vô vọng của một thứ hư vô...\",\"local_images\":[\"images/poem_331_img_0.webp\"]},{\"id\":297,\"title\":\"Lệ rơi rơi bên ánh mắt xa xăm\",\"date\":\"2015-01-27T23:30:31\",\"date_formatted\":\"27 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Lệ rơi rơi bên ánh mắt xa xăm\\n\\nTừ sâu thẳm thời gian có đọng lại\\n\\nChút vương tình thơ dại của thuở nào\\n\\nTrót lỡ trao khi mưa rào chợt đến.\\n\\nRồi cuốn đi bao yêu mến nồng nàn\\n\\nĐời gian nan khi hai đường chia lối\\n\\nBước bên nhau nhưng vội cách xa vời\\n\\nKẻ cố gắng đợi người nơi xa ấy\\n\\nNgười nơi đây lại chẳng bước chung đường\\n\\nHai kẻ quen cứ như dần xa lạ\\n\\nCách xa nhau mãi cả một đoạn đường\\n\\nChẳng đủ dài như phố phường đông đúc\\n\\nNhưng xa cách cả một khúc tâm hồn...\",\"local_images\":[\"images/poem_297_img_0.webp\"]},{\"id\":295,\"title\":\"Tết này có thêm thành viên nhí\",\"date\":\"2015-01-26T00:00:33\",\"date_formatted\":\"26 tháng 1, 2015\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Tết này có thêm thành viên nhí\\n\\nCuộc sống có thêm điều thú vị\\n\\nNâng ly ta chúc thành viên nhí\\n\\nTrăm ngàn hạnh phúc, triệu tỷ vui!\\n\\n\\nGia đình quây quần bên bếp nhỏ\\n\\nChẳng cần phải sợ chẳng cần lo\\n\\nMột mái nhà xinh thật nho nhỏ\\n\\nDù cho sóng gió chẳng phải lo\",\"local_images\":[\"images/poem_295_img_0.webp\"]},{\"id\":160,\"title\":\"Con mệt lắm rồi thượng đế ơi\",\"date\":\"2015-01-17T23:34:59\",\"date_formatted\":\"17 tháng 1, 2015\",\"genre\":\"Thất ngôn bát cú\",\"content_text\":\"Con mệt lắm rồi thượng đế ơi\\n\\nĐôi chân con bước, lệ con rơi\\n\\nMắt ướt đẫm đêm dài trắng xóa\\n\\nHéo hon tàn như lá mùa thu!\\n\\n\\nGiấc mơ xưa như đã ngủ vùi\\n\\nVào hư không nhưng lòng vẫn nhói\\n\\nMỗi bước đi gánh cả ngàn cân\\n\\nĐày ta xuống trần đầy u uất\",\"local_images\":[\"images/poem_160_img_0.webp\"]},{\"id\":122,\"title\":\"Mạnh mẽ đến đâu em vẫn là con gái\",\"date\":\"2015-01-15T09:44:37\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Mạnh mẽ đến đâu em vẫn là con gái\\n\\nMệt mỏi rồi em biết tựa vào ai\\n\\nMột bờ vai vẫn hoài mong đợi\\n\\nTìm được rồi hay lạc chốn xa xôi!\\n\\n\\nMột bước chân dường như còn hụt hẫng\\n\\nLạc giữa dòng đầy đấng mày râu\\n\\nMạnh mẽ đến đâu em vẫn là con gái\\n\\nMệt mỏi rồi, đời ngang trái phải không em\",\"local_images\":[\"images/poem_122_img_0.webp\"]},{\"id\":119,\"title\":\"Tôi gửi vào thơ một chút buồn\",\"date\":\"2015-01-15T09:43:05\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Thất ngôn\",\"content_text\":\"Tôi gửi vào thơ một chút buồn\\n\\nĐể cho dòng lệ đắng thôi tuôn\\n\\nDòng lệ buồn như sầu nhân thế\\n\\nTắm trong tim cả huyết lệ tình!\\n\\n\\nKiếp nhân sinh là mê hay tỉnh\\n\\nLạc giữa dòng sầu đắng cô liêu\\n\\nMột chữ yêu sao nhiều cay đắng\\n\\nNuốt ngược vào đỏ thắm máu tươi\\n\\n\\nTừng nhịp thở lười như sông nhỏ\\n\\nTrôi theo dòng đời có vui đâu\\n\\nSầu đã sầu, sầu càng nhung nhớ\\n\\nChờ đã chờ, đợi đến bao giờ...\",\"local_images\":[\"images/poem_119_img_0.webp\"]},{\"id\":116,\"title\":\"Nỗi cô đơn không tên mà vẫn nhớ\",\"date\":\"2015-01-15T09:40:45\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Nỗi cô đơn không tên mà vẫn nhớ\\n\\nChén rượu sầu không uống mà vẫn say\\n\\nĐời cứ quay sao ta hoài vô thức\\n\\nBước ngược đường mà mong sẽ thấy nhau!\\n\\n\\nĐời bể dâu hay mang sầu nhân thế\\n\\nGiọt lệ buồn cứ thế chẳng thể ngưng\\n\\nTa mãi vậy bước trên từng phố nhỏ\\n\\nVẫn một mình với gió lạnh từng cơn...\",\"local_images\":[\"images/poem_116_img_0.webp\"]},{\"id\":113,\"title\":\"Em là ai mà mắt nai nhung nhớ\",\"date\":\"2015-01-15T09:38:55\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Em là ai mà mắt nai nhung nhớ\\n\\nLặng lẽ buồn gieo nhịp thở trong anh\\n\\nTrời trong xanh như muôn ngàn nỗi nhớ\\n\\nChút thẫn thờ theo gió gửi về ai!\\n\\n\\nTình có sai khi ta hoài nhung nhớ\\n\\nĐã vương tình nhưng vờ chẳng nhớ nhung\\n\\nĐời đã chẳng bước chung về một phía\\n\\nSao cứ tìm những tia nắng mong manh\\n\\n\\nThắp lên chút hy vọng rồi sẽ tắt\\n\\nLụi tàn dần theo nắng lúc hoàng hôn\\n\\nChẳng thể ôm người vào trong giấc mộng\\n\\nĐành để người mơ mộng chốn nhân gian\",\"local_images\":[\"images/poem_113_img_0.webp\"]},{\"id\":110,\"title\":\"Ngày xưa má đỏ hây hây\",\"date\":\"2015-01-15T09:37:45\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Ngày xưa má đỏ hây hây\\n\\nNgày nay tóc phải đỏ vầy mới sang\\n\\nNgày xưa má đỏ dịu dàng\\n\\nNgày nay tóc đỏ còn sang hơn nhiều!\\n\\n\\nHay là em đã làm liều\\n\\nNhuộm ngay tóc đỏ để xiêu lòng anh\\n\\nDù cho mưa gió tanh bành\\n\\nTóc em vẫn đỏ để dành cho anh\",\"local_images\":[\"images/poem_110_img_0.webp\"]},{\"id\":107,\"title\":\"Mưa nhớ ai mưa giăng sầu nhân thế\",\"date\":\"2015-01-15T09:35:42\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Mưa nhớ ai mưa giăng sầu nhân thế\\n\\nGiọt lệ buồn đỏ khóe ướt mi cay\\n\\nChút cồn cào những đêm nao giá lạnh\\n\\nGiờ một mình cứ rét buốt tim ta!\\n\\nĐông đã qua nhưng sao ta vẫn lạnh\\n\\nMột bước đi như cả thế kỷ sầu\\n\\nChờ bóng hình đang dần chút phai phôi\\n\\nTheo sương khói nhưng chẳng thể tan biến\\n\\nMộng mị dần bên giấc ngủ hằng đêm\\n\\nChợt tỉnh giấc giữa một chút êm đềm\\n\\nCùng nỗi nhớ sẽ mãi là dĩ vãng\",\"local_images\":[\"images/poem_107_img_0.webp\"]},{\"id\":104,\"title\":\"Dò sông dò biển dễ dò\",\"date\":\"2015-01-15T09:34:00\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Dò sông dò biển dễ dò\\n\\nMấy ai lấy thước mà đo lòng người\\n\\nLòng người sâu lắm ai ơi\\n\\nNhưng sao bằng được miệng đời thế gian!\\n\\n\\nGian nan trong một kiếp đời\\n\\nVui đây, sầu đó bởi lời thế gian\\n\\nThôi thì cũng chẳng muộn màng\\n\\nSống sao để thấy đời càng vui hơn\\n\\nSống sao cho đúng với mình\\n\\nSống cho đời của người mình quan tâm\",\"local_images\":[\"images/poem_104_img_0.webp\"]},{\"id\":101,\"title\":\"Còn đâu nữa những đêm dài chung lối\",\"date\":\"2015-01-15T09:29:31\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Còn đâu nữa những đêm dài chung lối\\n\\nBước bên nhau cũng chẳng nói nên lời\\n\\nNgười bên ta nhưng xa vào tâm trí\\n\\nKhẽ hững hờ buông nhẹ cánh tay ai!\\n\\n\\nHai thế giới của người không cùng hướng\\n\\nSẽ xa dần chắc chỉ đợi thời gian\\n\\nBước vội vàng qua những cơn sầu khổ\\n\\nĐể sau lưng một kiếp số an bài\",\"local_images\":[\"images/poem_101_img_0.webp\"]},{\"id\":98,\"title\":\"Ngủ đi em, chẳng còn ai bên cạnh\",\"date\":\"2015-01-15T09:24:35\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Ngủ đi em, chẳng còn ai bên cạnh\\n\\nĐể vỗ về khi gió lạnh đầu hôm\\n\\nHay những buổi, chiều vừa tắt nắng\\n\\nCũng chẳng còn kẻ đón người đưa!\\n\\n\\nChẳng còn chi khi mưa vừa chợt đến\\n\\nĐể hạt buồn ướt đẫm cánh tay ta\\n\\nNgười đã xa, chỉ còn ta ở lại\\n\\nÔm mối sầu của một kẻ tình si\",\"local_images\":[\"images/poem_98_img_0.webp\"]},{\"id\":95,\"title\":\"Giữa cuộc vui cũng có tôi ngồi đó\",\"date\":\"2015-01-15T09:22:39\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Giữa cuộc vui cũng có tôi ngồi đó,\\n\\nNhư dòng đời mang theo cơn gió buồn\\n\\nNhững tiếng cười mang theo nhiều thanh sắc\\n\\nNhưng nỗi sầu nơi mắt lệ xa xăm!\\n\\n\\nĐời trăm năm, đời vẫn là bể khổ\\n\\nSuối yêu thương là lệ đổ tuôn trào\\n\\nGió dạt dào chẳng bao giờ ngừng thổi\\n\\nĐể lệ trong tim cứ nối tiếp tuôn trào\\n\\n\\nTrời nhiều sao nhưng bao giờ với được\\n\\nNgước mắt nhìn, đời cứ bước thênh thang...\",\"local_images\":[\"images/poem_95_img_0.webp\"]},{\"id\":92,\"title\":\"Cô đơn lặng lẽ mối tình sầu\",\"date\":\"2015-01-15T09:21:00\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Thất ngôn tứ tuyệt\",\"content_text\":\"Cô đơn lặng lẽ mối tình sầu\\n\\nBuồn vương một chút lệ thêm đau\\n\\nNắng gió phai tàn theo lá úa\\n\\nLệ sầu theo nắng lệ tuôn rơi\",\"local_images\":[\"images/poem_92_img_0.webp\"]},{\"id\":89,\"title\":\"Vì ai mẹ phải mưu sinh\",\"date\":\"2015-01-15T09:19:17\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Vì ai mẹ phải mưu sinh\\n\\nVì ai mẹ phải dầm mình dưới mưa\\n\\nVì ai mẹ nhịn cơm trưa\\n\\nVì ai mẹ phải cày bừa sớm hôm!\\n\\n\\nMột mai thân mẹ gầy còm\\n\\nMột mai rồi chẳng sớm hôm vỗ về\\n\\nMột mai mắt mẹ não nề\\n\\nMột mai lòng mẹ con về đợi mong\\n\\n\\nChờ trông dáng mẹ lưng còng\\n\\nChờ trông những lúc gió giông ùa về\\n\\nChờ trông sau những cơn mê\\n\\nChờ trông con có trở về như xưa\\n\\n\\nRồi đây tóc sẽ bạc màu\\n\\nRồi đây da sẽ đậm màu chân chim\\n\\nRồi đây khi gió lặng im\\n\\nRồi đây tim mẹ lặng tìm tên con\",\"local_images\":[\"images/poem_89_img_0.webp\"]},{\"id\":86,\"title\":\"Đâu phải khóc là khổ\",\"date\":\"2015-01-15T09:16:54\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Ngũ ngôn\",\"content_text\":\"Đâu phải khóc là khổ\\n\\nĐâu phải cười mới vui\\n\\nĐôi lúc cười trên môi\\n\\nNhưng lệ đổ trong tim!\\n\\nNhững lúc lặng im\\n\\nLòng lại đầy tâm sự\\n\\nNhững lúc khóe mắt cay\\n\\nNhưng đời càng cay đắng\\n\\nLệ chỉ chực tuôn trào\\n\\nNhưng nuốt ngược vào tim...\",\"local_images\":[\"images/poem_86_img_0.webp\"]},{\"id\":83,\"title\":\"Một kẻ ra đi một kẻ sầu\",\"date\":\"2015-01-15T09:15:12\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Thất ngôn\",\"content_text\":\"Một kẻ ra đi một kẻ sầu\\n\\nĐường tình chia lối lệ tuôn rơi\\n\\nMắt ướt hoen đôi mi bé nhỏ\\n\\nLệ trào trong đáy bể cô liêu!\\n\\nHồn lạnh hoang tàn sầu thêm khổ\\n\\nCô đơn lẻ bóng lệ thêm rơi...\",\"local_images\":[\"images/poem_83_img_0.webp\"]},{\"id\":80,\"title\":\"Đông đã đến trên những cành hoa tàn héo úa\",\"date\":\"2015-01-15T09:13:01\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Đông đã đến trên những cành hoa tàn héo úa\\n\\nSương lại về trên cành lá chơi vơi\\n\\nRun run se lạnh bình minh đến\\n\\nĐông sang, sẽ qua, nắng xuân về...\",\"local_images\":[\"images/poem_80_img_0.webp\"]},{\"id\":77,\"title\":\"Một mình thân ốc lang thang\",\"date\":\"2015-01-15T09:11:03\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Một mình thân ốc lang thang\\n\\nTìm đâu chốn nghỉ thế gian bộn bề\\n\\nGiữa đời còn lắm u mê\\n\\nTrốn trong thân ốc tỉ tê một mình!\\n\\n\\nNgười ăn vương chút sự tình\\n\\nKhông ăn đừng nỡ đem tình vứt đi\\n\\nSầu bi trong một kiếp đời\\n\\nGửi trong thân ốc, nhồi nơi nhân tình\",\"local_images\":[\"images/poem_77_img_0.webp\"]},{\"id\":74,\"title\":\"Tình như chiếc lá hững hờ\",\"date\":\"2015-01-15T09:06:43\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Tình như chiếc lá hững hờ\\n\\nBên cây rồi cũng có ngày biệt ly\\n\\nSẽ là gì khi cây chẳng còn lá\\n\\nLúc đông về nghe buốt giá con tim!\\n\\n\\nGió từ đâu mang đến muộn phiền\\n\\nCuốn theo lá ngả nghiêng chốn nào\\n\\nCây chỉ muốn ngã nhào về phía lá\\n\\nNhưng chẳng thể dẫu là một chút\",\"local_images\":[\"images/poem_74_img_0.webp\"]},{\"id\":71,\"title\":\"Cuộc đời có lắm đắng cay\",\"date\":\"2015-01-15T09:04:43\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Cuộc đời có lắm đắng cay\\n\\nTình yêu rồi cũng có ngày hợp tan\\n\\nMưa reo cùng gió trên ngàn\\n\\nTrút cơn mưa xuống muôn vàn nỗi đau!\\n\\n\\nTình kia dẫu có đậm sâu\\n\\nMột mai rồi cũng sầu đau một mình\\n\\nLặng thinh nghe một chút tình\\n\\nVang trong vô vọng đời mình sớm mai\\n\\n\\nĐường tình còn lắm chông gai\\n\\nChờ trong tiếng gió giọng ai gọi mình\\n\\nĐường tình rồi lại đường tình\\n\\nNghe trong vô vọng đời mình cô đơn\\n\\n\\nTình kia giờ đã dỗi hờn\\n\\nBỏ ta đi mất chẳng mong đợi gì\",\"local_images\":[\"images/poem_71_img_0.webp\"]},{\"id\":68,\"title\":\"Nhậu đi em cho đời hết sầu bi\",\"date\":\"2015-01-15T09:01:40\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Nhậu đi em cho đời hết sầu bi\\n\\nĐường còn dài làm gì mà cứ khóc\\n\\nLệ đã rơi đâu chắc sẽ qua mau\\n\\nĐời muôn màu đâu chỉ màu đen mãi!\\n\\nQua đêm tối thì mai trời sẽ sáng\\n\\nSương sẽ tàn khi ánh nắng chói chang\\n\\nĐời còn dài sẽ còn nhiều ngang trái\\n\\nTrải lòng ra để ngày mai rồi sẽ khác\\n\\nNắng màu vàng sẽ soi cuộc đời ta\\n\\nNhững góc khuất rồi chỉ là quá khứ\",\"local_images\":[\"images/poem_68_img_0.webp\"]},{\"id\":65,\"title\":\"Em...em là ai mà quay vội bước đi\",\"date\":\"2015-01-15T08:57:04\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Em...em là ai mà quay vội bước đi\\n\\nĐể mình anh với vô vàn cảm xúc\\n\\nKhi buồn vương có lúc lại sầu bi\\n\\nVì đã gặp khi chẳng hề quen biết!\\n\\nMà lòng anh cứ luyến tiếc mãi người đi\\n\\nTrời có sai khi cho ta gặp mặt\\n\\nĐày đọa thân anh với nỗi nhớ vô vàn\",\"local_images\":[\"images/poem_65_img_0.webp\"]},{\"id\":62,\"title\":\"Trung Thu năm đó em có anh\",\"date\":\"2015-01-15T08:55:10\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Trung Thu năm đó em có anh\\n\\nMà sao nay lại thấy lạnh đôi tay\\n\\nBàn tay ai đã từng nắm lấy\\n\\nGiờ đã buông vì hờ hững tim ai!\\n\\n\\nEm đã sai hay cuộc đời là vậy\\n\\nChữ vô tình sao cuốn lấy tim ai\\n\\nĐể ngày mai chẳng còn ai đó nữa\\n\\nLau nước mắt mỗi khi em buồn khổ\\n\\n\\nHay vô tình nắm lấy tay lạnh giá\\n\\nLúc đông về bên từng ngả đường xưa\\n\\nNhững ngày nắng hay mưa tầm tã\\n\\nMột mình em vội vã bước đi\\n\\n\\nKhi ngoảnh lại chẳng thấy anh ở đó\\n\\nChỉ còn sương với gió lạnh tim em\\n\\nTrời nhá nhem dần buông mọi nẻo\\n\\nBóng em buồn in dưới bóng trăng kia\\n\\n\\nMột mình em cứ vội vã đi về\\n\\nBuông chút buồn chút gió với trăng sao...\",\"local_images\":[\"images/poem_62_img_0.webp\"]},{\"id\":59,\"title\":\"Nhớ chi những lúc đắng cay\",\"date\":\"2015-01-15T08:53:12\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Nhớ chi những lúc đắng cay\\n\\nYêu chi những kẻ đọa đày con tim\\n\\nSao ta cứ mãi kiếm tìm\\n\\nCon tim của kẻ chẳng còn có ta!\\n\\n\\nHoàng hôn là lúc chiều tà\\n\\nĐắng cay là lúc ta chia đôi đường\\n\\nDẫu rằng còn chút vấn vương\\n\\nLối kia không thể cùng đường nhau đi\\n\\n\\nTiếc chi một chút tình si\\n\\nVương chi một chút lệ bi với sầu\\n\\nMai sau có lúc gặp nhau\\n\\nNgười như kẻ lạ chẳng đau chẳng buồn\",\"local_images\":[\"images/poem_59_img_0.webp\"]},{\"id\":56,\"title\":\"Tôi nằm đó nhìn lên ô cửa sổ\",\"date\":\"2015-01-15T08:49:56\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Tôi nằm đó nhìn lên ô cửa sổ\\n\\nNơi ánh đèn lấp ló khẽ chen vào\\n\\nNgoài kia gió vẫn cứ mãi rì rào\\n\\nMưa từng cơn buốt cả vào tâm can!\\n\\n\\nNgười thấy lạnh nhưng lòng vẫn ấm áp\\n\\nBởi xung quanh đầy ắp những bức tường\\n\\nNơi gió sương chẳng thể nào chạm đến\\n\\nTấm thân gầy gò nhỏ bé mong manh\\n\\n\\nBởi những anh kỹ sư đã thiết kế\\n\\nXây dựng nên mái ấm cho mọi người\\n\\nMặc nắng mưa vẫn luôn mãi tươi cười\\n\\nĐem tấm lòng vào từng trang giấy trắng\\n\\nXây đắp nên ngay ngắn một mái nhà\\n\\nNơi chúng ta luôn được chở che\\n\\nNơi hạnh phúc san sẻ với mọi người\\n\\nNơi tiếng cười luôn vang vọng mãi\\n\\nVới tháng năm với những người xây dựng\",\"local_images\":[\"images/poem_56_img_0.webp\"]},{\"id\":53,\"title\":\"Ai còn mẹ xin đừng làm mẹ khóc\",\"date\":\"2015-01-15T08:47:40\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Ai còn mẹ xin đừng làm mẹ khóc\\n\\nĐể mẹ buồn hay mắt lệ tuôn rơi\\n\\nĐã đi qua bao cay đắng cuộc đời\\n\\nVẫn bên con dẫu bể đời giông tố!\\n\\nMẹ thương con từ tiếng khóc chào đời\\n\\nĐến khi cả cuộc đời mẹ xa khuất\\n\\nNhớ những đêm khi gió lạnh ùa về\\n\\nVẫn lặng lẽ giữa căn phòng khuya vắng\\n\\nThắp lên bao ánh nắng của tình thương\\n\\nĐôi vai gầy với sương gió tháng năm\\n\\nChở che con qua năm dài tháng ngắn\\n\\nDẫu biết rằng mai đây con xa vắng\\n\\nLắng tình thương để sau này con bước tiếp\\n\\nVào đường đời đầy xô ngã bon chen\\n\\nKhi ánh đèn cũ hiu hắt đêm về\\n\\nMột mình mẹ chỉ lặng lẽ nơi nào\\n\\nChờ tin con mà con nào hay biết\\n\\nChỉ những lúc giữa dòng đời nghiệt ngã\\n\\nXô con xuống với sa ngã cuộc đời\\n\\nChỉ mình con chơi vơi nơi xứ lạ\\n\\nVẫn là mẹ, không phải bờ bến lạ\\n\\nĐể con tìm về bên mái lá bình yên\\n\\nNơi có mẹ, nơi không phải muộn phiền\\n\\nSuốt đời con chẳng phải cứ kiếm tìm\\n\\nNơi chốn ấy trong tim mẹ có con\",\"local_images\":[\"images/poem_53_img_0.webp\"]},{\"id\":50,\"title\":\"Con tim là tim của anh\",\"date\":\"2015-01-15T08:46:15\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Con tim là tim của anh\\n\\nMà sao nó mãi chạy quanh chốn nào\\n\\nGặp em thì nó hồng hào\\n\\nKhông em như nó rơi vào hư không\",\"local_images\":[\"images/poem_50_img_0.webp\"]},{\"id\":47,\"title\":\"Giữa đêm mưa gió bão bùng\",\"date\":\"2015-01-15T08:45:14\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Giữa đêm mưa gió bão bùng\\n\\nChui ra khỏi mùng, đắp mền làm thơ\\n\\nNào đâu ai biết chữ ngờ\\n\\nMuỗi đâu bay đến văng thơ với tình!\\n\\nRồi đâu lại bất thình lình\\n\\nChui vô rồi lại một mình làm thơ\",\"local_images\":[\"images/poem_47_img_0.webp\"]},{\"id\":44,\"title\":\"Tôi như một kẻ không nhà\",\"date\":\"2015-01-15T08:42:07\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Tôi như một kẻ không nhà\\n\\nLang thang phố xá, la cà công viên\\n\\nLâu lâu lại cũng bị điên\\n\\nXách con Wave chiến ngó nghiêng phố phường!\\n\\n\\nMột hôm lại chẳng bị thương\\n\\nMà sao đau nhói nơi đường máu ra\\n\\nPhía xa xa sau một mái nhà\\n\\nCó cô em gái mắt hoa đang cười\\n\\n\\nDáng người nhỏ bé xinh xinh\\n\\nMắt như biết hát môi xinh má hồng\\n\\nNhìn em má đỏ hồng hồng\\n\\nTim anh cũng thấy nao lòng quá đi\\n\\n\\nTìm quanh chẳng có cây si\\n\\nĐể anh đem đến trồng ngay nhà nàng\\n\\nNgày ngày sẽ chẳng vội vàng\\n\\nNgồi ngay cây ấy tặng nàng bài thơ\\n\\n\\nTim anh đã trót dại khờ\\n\\nYêu ngay ánh mắt ngây thơ mơ màng\\n\\nƯớc gì anh cưới được nàng\\n\\nĐể hai đứa mãi mơ màng làm thơ\",\"local_images\":[\"images/poem_44_img_0.webp\"]},{\"id\":41,\"title\":\"Có khi nào trên đường đời tấp nập\",\"date\":\"2015-01-15T08:38:29\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Có khi nào trên đường đời tấp nập\\n\\nTa vô tình khẽ bước qua nhau\\n\\nBiết mai sau sẽ không còn nữa\\n\\nCái ôm nồng giữa gió mùa đông!\\n\\n\\nLạc mất vòng tay giữa dòng đời vô tận\\n\\nNuối tiếc nhìn sầu hận mấy ai hay\\n\\nTa cứ say để đời chẳng bao giờ tỉnh\\n\\nMen rượu nồng làm bạn với trăng sao\\n\\n\\nTrăng trên cao trăng nào hay biết\\n\\nKẻ dưới này vẫn lẻ chiếc một mình\\n\\nGió từ đâu gió mang sầu đến\\n\\nMưa chốn vắng trút sầu đắng xuống ta\\n\\n\\nÁnh chiều mang một chút tà\\n\\nBiển xa sóng đánh gọi ta một mình\\n\\nThuyền kia đã mãi xa bờ\\n\\nBến đây sẽ lại bơ vơ một mình\\n\\n\\nCuộc đời sẽ tỉnh hay mê\\n\\nĐường về có mãi lê thê một mình\\n\\nTrời sinh chi một chữ tình\\n\\nĐể ngàn người mãi thất tình trời ơi\",\"local_images\":[\"images/poem_41_img_0.webp\"]},{\"id\":38,\"title\":\"Anh tìm em giữa đời thanh vắng\",\"date\":\"2015-01-15T08:36:04\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Anh tìm em giữa đời thanh vắng\\n\\nNhư gắng tìm mây trắng giữa bão giông\\n\\nGiữa dòng đời cứ mãi quay cuồng\\n\\nNhư kiếm tìm một vòng tay nắm lấy!\\n\\nChợt nhận ra, ồ sao khó quá vậy\\n\\nNắm được rồi cũng dễ mấy buông tay\",\"local_images\":[\"images/poem_38_img_0.webp\"]},{\"id\":35,\"title\":\"Tôi đi dưới ánh trăng tà\",\"date\":\"2015-01-15T08:34:46\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Tôi đi dưới ánh trăng tà\\n\\nĐể quên đi chút mặn mà đầu môi\\n\\nNgười vội đến rồi vội đi\\n\\nĐem theo chút lệ vương mi nghẹn ngào!\\n\\n\\nĐêm đêm nghe gió dạt dào\\n\\nNỗi sầu cô quạnh nơi nao tìm về\\n\\nDưới trăng nơi đã hẹn thề\\n\\nSông kia đã cuốn lời thề theo trăng\\n\\n\\nBâng khuâng mang chút nặng lòng\\n\\nTrút vào nỗi nhớ chờ mong đợi gì\\n\\nTrách chi một phút tình si\\n\\nBiết mình rồi sẽ sầu bi một đời\\n\\n\\nGió yên cho trời thêm lặng\\n\\nĐêm càng dài càng đè nặng tim ta\\n\\nDẫu rằng rất khó phôi pha\\n\\nQuên đi từng chút để ta đỡ buồn.\",\"local_images\":[\"images/poem_35_img_0.webp\"]},{\"id\":32,\"title\":\"Giọt lệ sầu lăn trên khóe mi cay\",\"date\":\"2015-01-15T08:33:19\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Giọt lệ sầu lăn trên khóe mi cay\\n\\nKỷ niệm buồn đeo theo nỗi nhớ thương\\n\\nSầu vấn vương trên môi hồng phai nhạt\\n\\nHồn lạc bước vào một cõi cô liêu\",\"local_images\":[\"images/poem_32_img_0.webp\"]},{\"id\":29,\"title\":\"Những kỷ niệm chôn vào trong dĩ vãng\",\"date\":\"2015-01-15T08:32:15\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Những kỷ niệm chôn vào trong dĩ vãng\\n\\nBỗng ùa về khi gió thoảng qua đây\\n\\nNgười đã đến phút giây đầu bỡ ngỡ\\n\\nRồi lại đi sau những thuở yêu đương!\\n\\nMang chút sầu vương trên khóe mắt\\n\\nGieo chút tình thắt chặt tim ta\",\"local_images\":[\"images/poem_29_img_0.webp\"]},{\"id\":26,\"title\":\"Tôi đi tìm lại vần thơ\",\"date\":\"2015-01-15T08:30:45\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Lục bát\",\"content_text\":\"Tôi đi tìm lại vần thơ\\n\\nBỏ quên trong mắt mộng mơ thuở nào\\n\\nHỏi rằng em có thấy không?\\n\\nHay là bão tố mưa giông cuốn rồi...\\n\\n\\nĐi tìm nửa mảnh tình côi\\n\\nNgày xưa anh gửi trên môi má nàng\\n\\nThế mà em nỡ sang ngang\\n\\nCầu Ô gãy nhịp lỡ làng duyên tơ...\\n\\n\\nTìm về lúc tuổi mộng mơ\\n\\nGặp em sao cứ ngẩn ngơ trong lòng\\n\\nGhét lây má thắm tươi hồng\\n\\nĐôi môi chúm chím mi cong, liễu gầy...\\n\\n\\nĐâu rồi cô bé thơ ngây\\n\\nChiều chiều hai đứa nhảy dây, trốn tìm\\n\\nĐưa tay ngắt đóa hoa sim\\n\\nCài lên mái tóc để tim lạc hồn...\\n\\n\\nTính em nũng nịu dỗi hờn\\n\\nTình xưa nghĩa cũ vùi chôn hết rồi?\\n\\nChỉ cần chút nhớ thương thôi\\n\\nVậy mà chẳng có để tôi tìm về...\",\"local_images\":[\"images/poem_26_img_0.webp\"]},{\"id\":23,\"title\":\"Người đã đi cho lòng ta hiu quạnh\",\"date\":\"2015-01-15T08:29:07\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Người đã đi cho lòng ta hiu quạnh\\n\\nRồi đêm dài sẽ đón lạnh mình ta\\n\\nGió thoảng qua bên người ta đó\\n\\nThấy rét lòng do thiếu một vòng tay!\\n\\n\\nTa đã say hay vì đời nghiêng ngả\\n\\nĐưa ta vào giữa muôn ngả bể dâu\\n\\nSẽ về đâu khi cơn đau là bạn\\n\\nChén muộn phiền ta rót cạn từng đêm\\n\\n\\nTrăng thêm sáng nhưng lòng ta vẫn tối\\n\\nBiết về đâu khi lối cũ không còn\\n\\nChút bâng khuâng từ lần đầu gặp gỡ\\n\\nNay đã thành vụn vỡ nhói con tim\\n\\n\\nGửi cho kẻ từng đêm là nỗi nhớ\\n\\nGiờ chẳng còn một góc nhỏ trong tim\\n\\nDù chỉ biết đó là điều chưa thể\\n\\nNhưng mặc kệ vẫn đang hoài cố gắng\",\"local_images\":[\"images/poem_23_img_0.webp\"]},{\"id\":20,\"title\":\"Gió lại gió, giữa dòng đời êm ả\",\"date\":\"2015-01-15T08:26:51\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Gió lại gió, giữa dòng đời êm ả\\n\\nNắng lại nắng, giữa phố vắng trưa hè\\n\\nMưa lại mưa, giữa đêm hè oi bức\\n\\nMây lại mây, giữa đong đầy nỗi nhớ!\\n\\n\\nGió thổi nắng đi cho mây mang mưa lại\\n\\nĐời nóng như trưa hè vắng nỗi nhớ thương\\n\\nDừng chân, nghiêng mình, trời nghiêng ngả\\n\\nNgửa đầu, ngước mắt, gió xôn xao\\n\\n\\nTình như giọt sương rơi trên lá\\n\\nGió mát ru tình trôi tựa mây\\n\\nMột phút lỡ yêu như trưa hè không gió\\n\\nNỗi nhớ xôn xao như gió thoảng đêm hè\\n\\n\\nMặt trăng non như tình yêu con trẻ\\n\\nKhúc khích cười khẽ lay động lòng ai\\n\\nNgười là ai để mai này lưu luyến\\n\\nÔm giấc nồng như hòa quyện trong mơ\\n\\n\\nChợt tỉnh giấc khi tuổi thơ òa về\\n\\nGiữ bóng hình để ta mãi mộng mơ\",\"local_images\":[\"images/poem_20_img_0.webp\"]},{\"id\":17,\"title\":\"Gửi tới em người con gái tôi yêu\",\"date\":\"2015-01-15T08:25:11\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Gửi tới em người con gái tôi yêu\\n\\nDù chẳng biết vì sao yêu nhiều thế\\n\\nThề với em giữa gió đông se lạnh\\n\\nNhớ đến em lòng không còn cô quạnh!\\n\\nGom nỗi nhớ thành vô vàn tia nắng\\n\\nGửi đến em một trưa nắng yêu thương\\n\\nKhông oi ả như nắng trưa thường thấy\\n\\nĐủ sưởi ấm lòng vì nơi ấy có anh\\n\\nCỏ vẫn xanh khi nắng vàng còn chiếu\\n\\nLòng vẫn yêu mặc đời thiếu tình yêu\",\"local_images\":[\"images/poem_17_img_0.webp\"]},{\"id\":275,\"title\":\"Tôi vẫn yêu cái loài hoa ban trắng\",\"date\":\"2015-01-15T08:20:02\",\"date_formatted\":\"15 tháng 1, 2015\",\"genre\":\"Tự do\",\"content_text\":\"Tôi vẫn yêu cái loài hoa ban trắng\\n\\nGiữa trưa hè dù nắng vẫn tươi cười\\n\\nNhớ đến ai hay nhớ đến nụ cười\\n\\nChút xao xuyến cho đời thêm mơ mộng!\\n\\nMở cõi lòng cho gió lạnh ùa về\\n\\nXóa cõi lòng cho vơi hoài nỗi nhớ\\n\\nLưu luyến tình dù chỉ còn mơ mộng\\n\\nKhóa cõi lòng để giữ chặt trong tim\\n\\nTình đã yên hãy chôn vào giấc ngủ\\n\\nVùi thật sâu cho chẳng nói thành lời!\",\"local_images\":[\"images/poem_275_img_0.webp\"]}]");
